window.SUMMARIES=[{"id": "L01", "title": "Introduction and Motivation", "oneLiner": "Why study and pursue entrepreneurship: definitions, entrepreneurial essence, corporate entrepreneurship, economic contributions, success/failure factors and why now is the right time in India.", "examRelevance": "Short theory answers on definition of entrepreneur, entrepreneurial essence, intrapreneurship, economic contributions and success factors (idea/business model, team, execution, funding, timing). Case questions may ask why large firms (Kodak, Nokia, Blackberry) decline or how entrepreneurs identify opportunities (Adani, Vaibhav Agrawal, Zerodha).", "sections": [{"heading": "Why learn entrepreneurship", "points": ["Regular jobs are being reshaped by automation and digital transformation; drones, AI, robotics, IoT are now the foundation of new business models.", "Firms want recruits with entrepreneurial thinking: initiative, quick adaptation, value creation, turning ideas into impact.", "Three motivations: become an entrepreneur, become job-market-fit, become a corporate entrepreneur (intrapreneur).", "Helps executives avoid strategic missteps that sank market leaders: Kodak, Blackberry, Nokia, IBM, Sears, Blockbuster, Microsoft.", "Also builds growth mindset, resilience, personal effectiveness; links to Maslow's hierarchy (self-actualization at top)."]}, {"heading": "Definition and traits of an entrepreneur", "points": ["Dictionary: one who organizes, manages, and assumes the risks of a business or enterprise.", "Has a compelling vision plus a comprehensive plan to execute it; identifies opportunities in adversities; failures do not deter.", "Comfortable with uncertainty and ambiguity; resolute, persevering, brave, open to ideas and advice.", "Founders' three traits: an insurgent's mission, an owner's mindset, obsession with the front line.", "Opportunities without much risk vanish in no time.", "Keywords: innovation, vision, alleviate pain, assertive risk taking, scalable model."]}, {"heading": "Entrepreneurial essence (six elements)", "points": ["Vision and innovation: anticipate market needs, create products that disrupt markets.", "Assertive (calculated) risk-taking; resilience and perseverance through failures.", "Opportunity recognition: spot market gaps and unmet needs, preempting competition.", "Value creation: first for customers, then self, employees, investors, society.", "Leadership and adaptability: build committed team, empower, communicate and share vision, adapt to change.", "Darwin: the most adaptable species survives, not the strongest or most intelligent."]}, {"heading": "Corporate entrepreneurship (intrapreneurship)", "points": ["Teams in an established company conceive, launch and manage a new business distinct from the parent but leveraging its assets, market position and capabilities.", "Employees act as entrepreneurs: creative, proactive, calculated risk, disruptive innovation within the firm's mission using its resources and security.", "Why Fortune 500 firms fail: 50% of 2000's Fortune 500 extinct; they lost entrepreneurial essence (failed to preempt market, envision needs, adapt, take risk, leadership vision).", "Facebook's little red book: 'If we don't create the thing that kills Facebook, someone else will' - innovate or perish."]}, {"heading": "Innovation, creative destruction and vision", "points": ["Entrepreneurs use innovation to alleviate problems, differentiate for competitive advantage, alleviate risks and create new business models.", "Innovation is anything done differently that creates better customer value, not just products.", "Schumpeter: creative destruction drives economic growth; ~88% of 1955 Fortune 500 gone by 2014.", "Vision = where the company wants to be long-term (Gates: PC in every home; Musk: humans on Mars). A shared vision is a hallmark of success.", "Crisis opens opportunities: 'Never let a good crisis go to waste' (Churchill)."]}, {"heading": "Types of business ventures", "points": ["Innovation- and vision-driven entrepreneurship (easily scalable).", "Corporate entrepreneurship / intrapreneurship.", "Small business; large corporates and cooperatives.", "Social entrepreneurship: for-profit and not-for-profit."]}, {"heading": "Economic contributions and why become an entrepreneur", "points": ["Raise government income, generate employment, promote savings, increase consumption, stimulate new demand.", "Improve technology landscape, diffuse foreign tech for self-reliance, bring forex, improve quality of life.", "Higher Global Entrepreneurship Index correlates with higher per-capita GDP and quality of life (GEDI 2019).", "Reasons: autonomy, wealth, value creation, social responsibility, accomplishment, solve agonizing pain, domain knowledge, favorable ecosystem, no other option."]}, {"heading": "Myths and failure data", "points": ["Myth: entrepreneurs born not made - fact: Dhirubhai, Narayana Murthy, Sunil Mittal, Jobs, Carnegie.", "Myth: needs lots of money - over 80% of new ventures are bootstrapped.", "Myth: born in business families / extroverts - mostly first-generation; 10 of 11 successful leaders introverts (cited in slides).", "Well-funded failures: 42% no market need (remedy validated learning), 29% ran out of cash (projected cash flow), 23% founder disharmony (team-building process).", "Causes: running out of money, no market need, founder disharmony, outcompeted, flawed business model, lack of focus.", "India lost entrepreneurial zeal under subjugation, became risk averse and favours government jobs."]}, {"heading": "Success factors and why now", "points": ["Factors: idea and business model (central; Google vs Yahoo), team (complementary skills), execution, funding, timing.", "Bill Gross: timing is the single biggest success factor. Victor Hugo: nothing defeats an idea whose time has come.", "India now: consumption power, demographic advantage, natural resources, knowledge workers, favorable policy, mature ecosystem.", "174+ Fortune 500 firms have Global Capability Centers in India; Indian firms compete globally (Hero, Bajaj, TVS, pharma, space, semiconductors).", "Most entrepreneurial qualities can be inculcated; unless you start you never know your capability. Fail forward (Maxwell)."]}], "cases": [{"name": "Gautam Adani", "crux": "College dropout who moved from brother's plastics business to PVC imports, Adani Exports, ports and power; key was eagle-eye opportunity identification and creating synergies across businesses."}, {"name": "Vaibhav Agrawal (Kirana Store Company)", "crux": "IT grad revamped dad's kirana store with product organisation and customer/inventory analytics; word-of-mouth led to revamping 100 stores in Tier II/III cities - opportunity spotted in grocers unable to adapt."}, {"name": "Zerodha", "crux": "Started 2010 to remove cost, support and technology barriers; disruptive pricing and in-house tech made it India's biggest broker. Opportunity: incumbents' incentives not aligned with customers; transparency as disruption."}, {"name": "Kodak, Nokia, Blackberry, Blockbuster, Sears, IBM", "crux": "Market leaders that declined by losing entrepreneurial essence and failing to adapt to changing customer needs."}, {"name": "Facebook little red book", "crux": "Culture of constant self-disruption: build what would kill you before others do."}, {"name": "Zepto and Jumbotail", "crux": "Zepto (Stanford dropouts, 2021, quick commerce) became a 2023 unicorn; Jumbotail is a B2B grocery marketplace - examples of new Indian unicorns."}, {"name": "Indian unicorns 2024-25", "crux": "Krutrim (first AI unicorn within a year), Porter, Rapido, Ather, Perfios, RateGain and others show the favourable Indian startup ecosystem."}, {"name": "Kalpana Saroj", "crux": "The real Slumdog Millionaire - rose from adversity to run multiple businesses, Padma Shri 2013."}, {"name": "Reliance Industries", "crux": "Example of large entrepreneurial contribution to national economy."}, {"name": "Moats (Uber, Facebook, Starbucks, Amazon, Google)", "crux": "Durable moats come from network effects, data and repeat engagement within an ecosystem."}], "keyTerms": [{"term": "Entrepreneur", "def": "One who organizes, manages and assumes the risks of a business, driven by vision and a plan to execute it."}, {"term": "Intrapreneurship", "def": "Corporate entrepreneurship: employees innovating and taking calculated risk to build new businesses within an established firm using its resources."}, {"term": "Entrepreneurial essence", "def": "Vision and innovation, calculated risk-taking, resilience, opportunity recognition, value creation, leadership and adaptability."}, {"term": "Creative destruction", "def": "Schumpeter's idea that innovation destroys old business models, driving growth and societal value."}, {"term": "Vision", "def": "Long-run aspiration of where the company wants to be; guides planning and must be shared."}, {"term": "Validated learning", "def": "Remedy for building what nobody wants: test hypotheses with customers before scaling."}, {"term": "Business moat", "def": "Durable competitive advantage, e.g. network effects, data, repeat engagement."}, {"term": "Per-capita GDP", "def": "Annual GDP divided by population; correlates with entrepreneurship index."}], "examAnswerTips": ["Define entrepreneur with the dictionary definition, then add vision, opportunity in adversity and calculated risk.", "For why large firms fail, cite 50% of Fortune 500 (2000) extinct, loss of entrepreneurial essence, Kodak/Nokia/Blackberry, and Facebook's innovate-or-perish.", "For opportunity identification, quote Adani (synergies, eagle eye), Vaibhav Agrawal (analytics for kirana), Zerodha (misaligned incentives, transparency).", "List success factors: business model, team, execution, funding, timing - stress timing (Bill Gross).", "Use failure stats 42/29/23 with remedies (validated learning, projected cash flow, team-building)."], "quiz": [{"q": "Per the lecture, which factor did Bill Gross find to be the single biggest reason for startup success?", "options": ["Funding", "Team", "Timing", "Idea"], "answer": 2, "why": "Slide 61: timing is the greatest success factor."}, {"q": "What share of new ventures are bootstrapped according to the slides?", "options": ["About 20%", "About 50%", "More than 80%", "Less than 1%"], "answer": 2, "why": "Myth of needing lots of money: >80% bootstrapped."}, {"q": "42% of well-funded ventures fail because of:", "options": ["Running out of cash", "No market need", "Founder disharmony", "Competition"], "answer": 1, "why": "Remedy is validated learning."}, {"q": "The three founder traits listed are insurgent's mission, owner's mindset and:", "options": ["Obsession with the front line", "Love of risk", "Technical genius", "Extroversion"], "answer": 0, "why": "Slide 30."}, {"q": "Creative destruction was propounded by:", "options": ["Drucker", "Schumpeter", "Darwin", "Gerber"], "answer": 1, "why": "Slide 37."}, {"q": "Zerodha's core opportunity was that:", "options": ["Brokers lacked branding", "Incumbent incentives were not aligned with customers", "There was no online trading", "Trading was illegal"], "answer": 1, "why": "They disrupted operationally with transparency and low pricing."}, {"q": "Corporate entrepreneurship creates a new business that:", "options": ["Is fully independent of the parent", "Is distinct but leverages parent's assets and capabilities", "Replaces the parent", "Is always a spin-off sold off"], "answer": 1, "why": "Slide 24 definition."}, {"q": "About what share of 2000's Fortune 500 companies are extinct today?", "options": ["10%", "25%", "50%", "88%"], "answer": 2, "why": "88% refers to 1955 vs 2014; 50% for 2000."}], "slug": "L01_Introduction", "excluded": "Crossed-out slides 22, 25, 28, 47–49, 51–53 excluded."}, {"id": "L02", "title": "Inspiring Stories of Entrepreneurs", "oneLiner": "Lessons from successful and failed entrepreneurs (Porter, Adani, Zepto, Dhirubhai Ambani, Karsanbhai Patel, Kalpana Saroj, Steve Jobs, Theranos, Nasty Gal, Byju's) on vision, opportunity, execution and ethics.", "examRelevance": "Case-based questions on how entrepreneurs identify opportunities in adversity (Dhirubhai's export-import, Porter's boring logistics, Nirma's low-cost detergent), why ventures collapse (Nasty Gal burn rate and no professional team, Byju's valuation chasing, Theranos deception), and when to hire a professional CEO/executive team.", "sections": [{"heading": "Core message", "points": ["Entrepreneurship can be learnt from both success and failure stories; most heroes started from humble backgrounds, busting myths.", "It does not matter how many resources you have; if you do not know how to use them, they will not be enough.", "Common blueprint: confidence, opportunity in adversity, relentless customer value, design-centric thinking, smart execution, adaptability, teamwork."]}, {"heading": "Opportunity identification patterns", "points": ["Spot overlooked or boring but massive pain points (Porter: intra-city logistics).", "Find gaps in incumbents' behaviour (Dhirubhai: exporters chased margin, not quality or delivery).", "Convert adversity into opportunity (Dhirubhai exported at a loss to earn forex for imports in 1960s).", "Cost leadership for underserved masses (Nirma at one-fourth price).", "Seize policy shifts (Adani after 1991 liberalisation; green energy early)."]}, {"heading": "Dhirubhai Ambani's strategies", "points": ["Self-learnt trade, accountancy, shipping, currency in Aden; built a network of associates who later became top employees.", "Started Reliance Commercial as spice trader with a table, two chairs and a shared phone.", "Quality and before-schedule delivery to quality-valuing customers; diversified from spice to yarn (Bamber) to textiles (Vimal) to refineries.", "Moved up value chain (yarn to fabric); imported modern plants instead of second-hand; sold directly to retailers bypassing mill resistance.", "Shared profits with investors: 'Loss is mine, profit I share' - mobilised huge capital."]}, {"heading": "Execution and scaling lessons", "points": ["Porter: perseverance over prestige, growth balanced with profitability, execution discipline over flashy ideas.", "Zepto: 10-minute delivery, best-in-class execution, customer experience, strong team.", "Nirma: focus on cost reduction, backward integration, latest technology.", "Kalpana Saroj's process focus: quality 100%, purity 99%, design 90%, product diversity 85%."]}, {"heading": "Nasty Gal: five success strategies", "points": ["Deep understanding of customers and their changing tastes.", "Eye on profit: sell for more than bought; profitable from day one; 93% inventory sold at full price.", "Social skills: #NastyGal hashtag, quick responses, everyone a marketer, real product images, DIY content, featuring customers.", "Consistent philosophy and uncompromised, consistent ethics."]}, {"heading": "Nasty Gal: four reasons it failed", "points": ["Cash is king: after VC money, lavish LA HQ, two stores, dedicated DC, heavy marketing - burn rate exploded.", "A CEO must love the job: she got distracted by book, podcast, TV show.", "Starting is easy, scaling is hard: should hire a complementary professional executive team early (Zuckerberg hired Sandberg as COO).", "Success is a long-term process, not a quick-million goal; bankruptcy Nov 2016, sold for $20M in 2017."]}, {"heading": "Ethics and valuation traps", "points": ["Theranos: unvalidated claims, culture of secrecy and fear, fraud; lesson - transparency, ethical leadership, rigorous validation.", "Byju's: chased $100B valuation via customer exploitation, acquisitions, employee pressure, non-disclosure; lesson - create customer value, not valuation.", "Takeaways: anyone can become an entrepreneur; not everyone is cut out for CEO - know when to hire a professional."]}], "cases": [{"name": "Porter (IIT KGP)", "crux": "Uttam Digga and Pranav Goel (with Vikas Chaudhary) left corporate jobs to solve unreliable intra-city transport for MSMEs; tech platform with 30 lakh MSMEs, 6 lakh drivers, FY25 revenue Rs 4,306 cr, profitable unicorn."}, {"name": "Gautam Adani", "crux": "College dropout, diamond sorter, then plastics, polymer imports, Adani Exports (1988), Mundra Port (1993/95); expanded after 1991 reforms into power, coal, airports and became world's largest renewable player - opportunity spotting and synergies."}, {"name": "Zepto", "crux": "Teenage Stanford dropouts built 10-minute delivery; won via execution, customer experience and team despite big rivals; valued $7B (2025)."}, {"name": "Dhirubhai Ambani", "crux": "First-generation entrepreneur from poverty; spotted quality gap in exports, used forex adversity as opportunity, moved up value chain to world-class refineries; Reliance ~3% of GDP and ~10% indirect tax."}, {"name": "Reliance Jio", "crux": "Disruptive 2016 entry saved India about $10B annually and surged data use; studies say it boosts per-capita GDP."}, {"name": "Karsanbhai Patel (Nirma)", "crux": "Chemistry grad lab technician made phosphate-free detergent in his backyard (1969), sold by bicycle at Rs 3/kg (one-fourth of rivals); cost leadership and backward integration built a Rs 42,500 cr group."}, {"name": "Kalpana Saroj", "crux": "Real Slumdog Millionaire; succeeded through obsessive process focus on quality and purity; Padma Shri 2013."}, {"name": "Steve Jobs", "crux": "Dropout who co-founded Apple in a garage; sold his van to fund the Apple I; licensed Xerox GUI/mouse for pre-IPO shares; ousted 1985, built NeXT and Pixar, returned 1997 - convert adversity into opportunity."}, {"name": "Theranos (Elizabeth Holmes)", "crux": "Claimed comprehensive tests from a few drops of blood, reached $10B valuation, but tech did not work; secrecy and fraud led to collapse and 11-year sentence."}, {"name": "Nasty Gal (Sophia Amoruso)", "crux": "Accidental push-type entrepreneur: sold an $18 jacket for $1000 on Myspace, built a $240M retailer with superb customer metrics; collapsed due to cash burn, distraction and no professional team; fought back with Girlboss."}, {"name": "Byju's (Byju Ravindran)", "crux": "Passion-for-teaching edtech grew to $22B, then chased valuation via acquisitions and customer exploitation, hid finances, defaulted, faced lawsuits; lesson: customer value over valuation."}], "keyTerms": [{"term": "Push-type entrepreneur", "def": "Someone who becomes an entrepreneur by chance or necessity rather than plan (e.g. Sophia Amoruso)."}, {"term": "First-generation entrepreneur", "def": "Founder without a family business background (e.g. Dhirubhai Ambani)."}, {"term": "Burn rate", "def": "Rate at which a company spends cash; Nasty Gal's leap was unsustainable."}, {"term": "Backward integration", "def": "Producing own inputs to cut cost and control quality (Nirma)."}, {"term": "Value-chain move", "def": "Shifting to higher value-added activity, e.g. yarn to fabric (Reliance)."}], "examAnswerTips": ["For opportunity identification quote Dhirubhai (quality gap, forex adversity), Porter (boring pain point), Nirma (affordable price for masses), Adani (liberalisation).", "For when to hire a professional CEO/executive team, cite Nasty Gal's Reason 3 and Zuckerberg hiring Sandberg early.", "For decisions diverging from conventional wisdom: Dhirubhai imported new plants vs second-hand, sold directly to retailers, shared profits with investors; Amoruso turned down most VC offers early.", "For ethics/valuation questions contrast Theranos and Byju's with Porter's profitable growth.", "Structure answers: situation, decision, outcome, lesson."], "quiz": [{"q": "Dhirubhai Ambani's slogan for investors was:", "options": ["Customer is king", "Loss is mine, profit I share", "Quality first", "Think big"], "answer": 1, "why": "Slide 18; it built investor trust and capital."}, {"q": "How did Dhirubhai overcome 1960s import restrictions?", "options": ["Smuggling", "Exporting rayon at a loss to earn forex for importing synthetic fibre", "Government loans", "Foreign partner"], "answer": 1, "why": "Opportunity in adversity."}, {"q": "Nirma was initially priced at about what fraction of cheapest popular detergents?", "options": ["Half", "One-fourth", "One-tenth", "Same"], "answer": 1, "why": "Rs 3/kg, one-fourth."}, {"q": "Which is NOT one of the four reasons Nasty Gal failed?", "options": ["Cash burn", "CEO distracted", "No professional executive team", "Poor customer understanding"], "answer": 3, "why": "Customer understanding was a success strategy."}, {"q": "The example of hiring a complementary executive early to scale is:", "options": ["Jobs hiring Sculley", "Zuckerberg hiring Sheryl Sandberg", "Byju hiring ambassadors", "Holmes hiring board"], "answer": 1, "why": "Slide 52."}, {"q": "Porter's key lesson was:", "options": ["Flashy idea", "Scaling while staying profitable through execution discipline", "Raising most capital", "Celebrity endorsement"], "answer": 1, "why": "Slide 5."}, {"q": "Byju's key lesson per the slides:", "options": ["Acquire aggressively", "Focus on customer value, not valuation", "Expand globally fast", "Use celebrities"], "answer": 1, "why": "Slide 61."}, {"q": "Nasty Gal sold what share of inventory at full price?", "options": ["50%", "75%", "93%", "100%"], "answer": 2, "why": "Industry norm is markdowns."}], "slug": "L02_Inspiring_Stories", "excluded": "Struck-through text on slide 58 excluded."}, {"id": "L03", "title": "Introduction to Financial Statements", "oneLiner": "Why cash is king and how the balance sheet, profit and loss account and cash flow statement are built and read, using a hostel stationery shop example.", "examRelevance": "Announced as short-answer only: expect definitions (balance sheet vs P&L vs cash flow), profit hierarchy formulas, COGS, depreciation, fixed vs current assets, operating cycle/receivable cycle, and the three cash flow heads.", "sections": [{"heading": "Cash is king", "points": ["Business cannot run without cash; book profit may be a mirage; only cash balance tells the real story.", "A major cause of startup failure is running out of cash: if one cannot manage finances, one cannot manage a business.", "Aerion failed despite a US$11.2 B order book and $1 B product investment, because it ran out of funds and did not raise early (no cash flow planning). Airware shut after burning $118M."]}, {"heading": "Purpose, stakeholders and perspectives", "points": ["Primary purpose: report the actual financial state of the company to all stakeholders.", "Stakeholders: founders/promoters/owners, shareholders, lenders (bankers), government (income tax, GST), economists, analysts, investors, employees, policymakers/statisticians.", "Three perspectives: entrepreneurs, other stakeholders, government (income tax). Owners may under- or over-report; data users become victims.", "Owner decisions driven by financials: cost cutting, pricing, hiring, hiving off, capacity augmentation, make vs outsource, borrowing, capital raising."]}, {"heading": "Accounting frauds", "points": ["Enron: reported $111 B revenue in 2000, overstated profit and hid debt; share fell from $90.75 (Aug 2000) to $0.67 (2002) then zero.", "WorldCom: second largest US phone company, fraudulently under-reported costs of $3.8 B and filed for bankruptcy.", "Satyam Computers: chairman Ramalinga Raju confessed accounts falsified by Rs 12,318 crore; thousands jobless."]}, {"heading": "Operating cycle and working capital", "points": ["Operating cycle: cash to raw materials to finished goods to sales to cash; numerically, the average period to complete this process.", "Example: fixed assets 10,000; raw material 1,000 + WIP 500 + finished goods 2,000 + receivables 2,500 - payables 2,000 = 4,000 for operating cycle; total 14,000.", "Receivable turnover = annual sales / average receivables = 40,000 / 10,000 = 4; receivable cycle = 365 / 4 = 91.25 days.", "Adani Enterprises: receivable cycle 90 days, payable cycle 126 days, so it holds suppliers' money (example of 36 days between 26.07.21 and 31.08.21). Managing creditors matters."]}, {"heading": "Double entry system", "points": ["Every business transaction involves two or more accounts, recorded in ledgers (cash ledger, sales ledger, purchase ledger).", "Cash purchase of Rs 500 raw material: cash account decreases, purchase account increases.", "Purchase of 500 with 300 cash and 200 credit affects three accounts: purchase 500, cash 300, accounts payable 200."]}, {"heading": "The statements", "points": ["Three major statements: balance sheet, profit and loss (income) statement, cash flow statement; a fourth is statement of changes in owners' (stockholders') equity.", "Balance sheet: snapshot of assets, liabilities and owner's equity at a particular point in time (e.g. as on 31.03.2021). Total assets must equal total liabilities.", "P&L: operational performance over a period (e.g. 01.04.2020 to 31.03.2021).", "Cash flow statement: cash sources and uses from operating, investing and financing activities, giving net cash flow for the period; reveals liquidity and corrects misperception from profit data."]}, {"heading": "Fixed vs current assets (stationery shop)", "points": ["Counter 500 + rack 600 + chair 400 = 1,500 fixed assets; stationery stock 5,000 + cash 500 = 5,500 current assets; total need Rs 7,000.", "Fixed (long-term) assets facilitate business and are not for sale; current (short-term) assets are meant to be converted into sales quickly.", "Same item can differ by business: a car is a current asset for a car maker but a long-term asset for a transport operator.", "Funding: own Rs 3,000 plus Rs 4,000 borrowed from friend Rohit gives financial closure. Later an employee at Rs 5,000/month and a Rs 10,000 billing machine are added."]}, {"heading": "Profit hierarchy", "points": ["Gross profit = Sales - COGS. Operating profit = Gross profit - operating expenses. PBT = Operating profit - interest. Net profit = PBT - income tax. Retained profit = Net profit - dividend.", "EBITDA: earnings before interest, tax, depreciation and amortization; compares companies eliminating differences in these items.", "Profit margin = profit as % of sales; the denominator is always sales.", "Example: sales 1000, COGS 600, GP 400, D&A 100, other opex 150, OP 150, interest 50, PBT 100, tax 20% = 20, NP 80, dividend 30, retained 50."]}, {"heading": "Why different profits", "points": ["Allow apple-to-apple comparison and reveal the cause of performance.", "Higher gross margin: better conversion of raw materials, energy-efficient process, higher price, input bargaining power, efficient manufacturing.", "Operating margin combines process and operational efficiency but ignores financing cost; PBT margin includes finance cost; net margin reflects tax management.", "Auto data 2019-20: M&M interest 44.6% of OP, Tata Motors PBT negative, Maruti interest only 0.94% of OP; high debt hurts PBT even if operations are efficient."]}, {"heading": "COGS, stock and depreciation", "points": ["COGS = opening inventory + purchases during year - closing inventory; e.g. 5,000 + 2,50,000 - 10,000 = 2,45,000.", "Closing stock is unsold inventory at year end; previous year's closing stock becomes this year's opening stock (taken from previous balance sheet).", "Depreciation: gradual apportioning of the cost of a tangible asset as expense over its useful life; charged in P&L instead of expensing all at once, avoiding profit volatility.", "Businesses depreciate assets differently for tax and for reporting to stakeholders. Proprietorship profit is clubbed with proprietor's personal income (slides use 30% tax for demonstration)."]}, {"heading": "Cash flow statement details", "points": ["Cash equivalents: short-term, highly liquid investments readily convertible to known cash with insignificant risk; normally maturity of three months or less.", "Indirect operating cash flow = net profit + depreciation + loss on asset sale - gain on asset sale - rise in current assets + fall in current assets + rise in current liabilities - fall in current liabilities.", "Sale value of fixed assets goes into investing activities. Investing: capital expenditure and investments.", "Financing: + net borrowing, + fresh equity, - dividend paid, - net investment in equity/debt of other companies.", "Bankers and analysts watch all three heads; founders focus on meeting cash needs and ending cash balance. Projected cash flow warns of shortfalls early."]}, {"heading": "Customer acquisition techniques", "points": ["Refund (Casper 100-night free trial), referrals (Airbnb, Uber, PayPal), SEO, content marketing (HubSpot; Backlinko one high-quality blog per month), transparency (Everlane), gamification (Mint)."]}], "cases": [{"name": "Aerion", "crux": "US$11.2 B order book and $1 B invested, yet failed by running out of funds; founder regretted not acting sooner, i.e. not preparing cash flow statements."}, {"name": "Airware", "crux": "Drone startup shut after burning $118M because it ran out of financial runway."}, {"name": "Enron, WorldCom, Satyam", "crux": "Accounting frauds (overstated profit, hidden debt, $3.8 B understated cost, Rs 12,318 crore falsified) destroyed investors and employees."}, {"name": "Adani Enterprises", "crux": "Receivables 90 days vs payables 126 days: the company uses suppliers' money, showing value of managing creditors."}, {"name": "Hostel stationery shop", "crux": "Rs 7,000 project (1,500 fixed + 5,500 current), financed 3,000 own + 4,000 loan, used to build P&L, balance sheet and cash flow."}, {"name": "M&M, Tata Motors, Maruti", "crux": "Comparison shows how interest burden and tax change the picture from operating profit to PBT and net margin."}, {"name": "Casper, HubSpot, Mint, Everlane", "crux": "Customer acquisition via refund trials, content marketing, gamification and transparency."}], "keyTerms": [{"term": "Balance sheet", "def": "Statement of assets, liabilities and owners' equity at a point in time."}, {"term": "Profit and loss account", "def": "Income statement showing operating performance over a period."}, {"term": "Cash flow statement", "def": "Summary of cash inflows and outflows from operating, investing and financing activities over a period."}, {"term": "Fixed assets", "def": "Long-term assets that facilitate business and are not meant for sale."}, {"term": "Current assets", "def": "Short-term assets such as inventory, receivables and cash meant to convert into sales quickly."}, {"term": "Operating cycle", "def": "Average period from cash to raw material, finished goods, sale and back to cash."}, {"term": "Double entry system", "def": "Every transaction affects two or more accounts recorded in ledgers."}, {"term": "EBITDA", "def": "Earnings before interest, tax, depreciation and amortization."}, {"term": "Depreciation", "def": "Gradual apportioning of the cost of a tangible asset as expense over its useful life."}, {"term": "Closing stock", "def": "Inventory unsold at year end; becomes next year's opening stock."}, {"term": "Cash equivalents", "def": "Highly liquid short-term investments (about three months maturity or less) with insignificant risk of value change."}], "formulas": [{"name": "Gross profit", "expr": "Sales - Cost of goods sold", "note": "Reflects conversion efficiency."}, {"name": "Operating profit", "expr": "Gross profit - Operating expenses", "note": "Operating expenses include depreciation and amortization."}, {"name": "Profit before tax", "expr": "Operating profit - Interest", "note": "Captures financing cost."}, {"name": "Net profit", "expr": "PBT - Income tax", "note": "Bottom line."}, {"name": "Retained profit", "expr": "Net profit - Dividend", "note": "Goes to reserves."}, {"name": "Profit margin", "expr": "Profit / Sales x 100", "note": "Denominator is always sales."}, {"name": "Cost of goods sold", "expr": "Opening inventory + Purchases - Closing inventory", "note": "Opening stock = previous year closing stock."}, {"name": "Receivable turnover and cycle", "expr": "Turnover = Annual sales / Average receivables; Cycle = 365 / Turnover", "note": "40,000/10,000 = 4; 365/4 = 91.25 days."}, {"name": "Operating cycle funds", "expr": "Raw material + WIP + Finished goods + Receivables - Payables", "note": "Money blocked in the cycle (example 4,000)."}, {"name": "Operating cash flow (indirect)", "expr": "Net profit + Depreciation + Loss on asset sale - Gain on asset sale - Increase in CA + Decrease in CA + Increase in CL - Decrease in CL", "note": "Depreciation added back because no cash left."}, {"name": "Balance sheet identity", "expr": "Total assets = Total liabilities (including equity)", "note": "Must always balance."}], "examAnswerTips": ["Contrast point in time (balance sheet) vs period (P&L, cash flow) explicitly.", "Name all three cash flow heads: operating, investing, financing.", "When asked why cash flow matters for startups, cite running out of cash (Aerion, Airware) and that profit can mislead.", "Write the profit hierarchy in order and remember income tax and dividend come after PBT.", "In COGS questions, opening stock comes from the previous year's balance sheet.", "Explain depreciation as non-cash expense added back in indirect cash flow."], "quiz": [{"q": "Which statement is a snapshot at a particular point in time?", "options": ["P&L account", "Cash flow statement", "Balance sheet", "Statement of sales"], "answer": 2, "why": "Balance sheet shows position as on a date; P&L and cash flow cover a period."}, {"q": "Opening inventory 5,000, purchases 2,50,000, closing inventory 10,000. COGS?", "options": ["2,65,000", "2,45,000", "2,55,000", "2,40,000"], "answer": 1, "why": "5,000 + 2,50,000 - 10,000 = 2,45,000."}, {"q": "Sales 1000, COGS 600, D&A 100, other opex 150, interest 50, tax 20%. Net profit?", "options": ["150", "100", "80", "50"], "answer": 2, "why": "GP 400, OP 150, PBT 100, tax 20, NP 80."}, {"q": "In that example, dividend is 30. Retained profit?", "options": ["50", "70", "80", "20"], "answer": 0, "why": "80 - 30 = 50."}, {"q": "Annual sales 40,000 cr, average receivables 10,000 cr. Receivable cycle?", "options": ["4 days", "45.6 days", "91.25 days", "126 days"], "answer": 2, "why": "Turnover 4; 365/4 = 91.25 days."}, {"q": "In the indirect method, an increase in current assets is:", "options": ["Added", "Subtracted", "Ignored", "Moved to financing"], "answer": 1, "why": "Cash is tied up, so increase in current assets is deducted."}, {"q": "Proceeds from sale of a fixed asset appear under:", "options": ["Operating activities", "Investing activities", "Financing activities", "Not shown"], "answer": 1, "why": "Slides note sale value of fixed assets goes to investment activity."}, {"q": "For the stationery shop, a rack worth Rs 600 is a:", "options": ["Current asset", "Fixed asset", "Liability", "Expense"], "answer": 1, "why": "It facilitates business and is not for sale."}, {"q": "A purchase of 500 paid 300 cash and 200 on credit affects how many accounts?", "options": ["One", "Two", "Three", "Four"], "answer": 2, "why": "Purchase, cash and accounts payable."}, {"q": "EBITDA is mainly used to:", "options": ["Compute tax", "Compare firms removing interest, tax, depreciation differences", "Find dividend", "Measure liquidity"], "answer": 1, "why": "Removes effects of capital structure, tax and depreciation."}, {"q": "Which is the primary cause of startup failure emphasised in this lecture?", "options": ["Too many customers", "Running out of cash", "High dividends", "Low depreciation"], "answer": 1, "why": "Cash is king; Aerion and Airware ran out of funds."}], "slug": "L03_Financial_Statements", "excluded": "Crossed-out slides 19–20 (debit/credit rules) excluded. Exam: short answers only."}, {"id": "L04", "title": "Myths and Realities of Entrepreneurship", "oneLiner": "Debunks common myths (born not made, risk lovers, need lots of money, VC funded, business families, loners, etc.) that stop people from starting or mislead them into failure.", "examRelevance": "True/false or short-answer questions on myths with facts and examples; links to questions on how much capital to raise (bootstrapping, under 1% VC-backed), premature scaling, and conventional wisdom vs reality.", "sections": [{"heading": "Why myths matter", "points": ["Myths are rarely discussed but cause apprehension; they stop people from starting or make them start without exploration.", "About 70% of adults in 52 economies think entrepreneurs enjoy high status (GEM 2017-18), yet few start ventures.", "No silver bullet: success combines hard work, innovation, market understanding, adaptability, perseverance and some luck.", "You know your capability only when you begin."]}, {"heading": "E-Myth: three personalities (Gerber)", "points": ["Entrepreneur: visionary, innovator, disrupts status quo, turns conditions into opportunities - lives in the FUTURE.", "Manager: practical, brings planning and order, holds on to status quo - lives in the PAST.", "Technician: if you want it done right, do it yourself - lives in the PRESENT."]}, {"heading": "Myths 1-4", "points": ["Born not made: Drucker - entrepreneurship is a learnable discipline; most successful founders are first-generation (Good to Great: 10 of 11).", "High risk lovers: they see opportunity where others see risk and take calculated risks; opportunity appeal is tied to risk, but they do not love risk.", "Need lots of money: over 80% bootstrapped (savings, credit cards, friends, sweat equity); flip side - some early money accelerates and reduces stress.", "In it for money: startups take years to profit; quick-money seekers quit; the main motive is independence."]}, {"heading": "Myths 5-8", "points": ["Born in business families: first-generation founders are the real wealth creators; capital-access gap shrinking with angels and VCs.", "First-gen advantages: educate themselves, resilient, fail fast and pivot, free of traditional baggage, superior value propositions.", "Must be young: early-stage entrepreneurship evenly spread across ages 18-64; youth gives energy, maturity gives experience and network.", "Ignore personal life: no different from executives; they schedule to keep weekends - not a boss who sits back.", "Most ventures fail: data misleading (mergers, takeovers, renaming); Fortune 500 average life fell from 61 to 15 years."]}, {"heading": "Myths 9-12", "points": ["High-tech wizards: not a common pattern; successful ones manage all aspects of business operations.", "Loners / extroverts: success needs networking, but Good to Great found 10 of 11 great-company CEOs introverts.", "Financed by VC: VCs have lower risk appetite and costlier money; less than 1% of new businesses are VC-backed; most use savings, friends, seed, grants, angels.", "Ruthless or deceptive: such founders spend time repairing relationships or fail (Theranos, Byju's)."]}, {"heading": "Product, scaling and funding myths", "points": ["Great product guarantees success - reality: market fit, timing, distribution, branding matter equally; execution and adoption differentiate.", "Scaling fast is always better - reality: premature scaling is a leading cause of failure; need operations, cash flow, retention.", "Funding equals success - reality: funding is only fuel; build value, not chase investors.", "Amazon's success mantra: disrupt status quo (sales and delivery channels), create value, alleviate pain, create unfair advantages."]}], "cases": [{"name": "Dhirubhai Ambani", "crux": "First-generation entrepreneur from poverty who dropped out, migrated to Aden and built world-class industries - busts born-not-made and family-business myths."}, {"name": "Narayana Murthy (Infosys)", "crux": "Co-founded Infosys in 1981 with $250 borrowed from his wife; now worth over Rs 8 lakh crore - busts need-lots-of-money myth."}, {"name": "Sunil Bharti Mittal", "crux": "Started with Rs 20,000 from his father making bicycle components, kept launching businesses; about $35B net worth."}, {"name": "Sabeer Bhatia", "crux": "Co-founded Hotmail with Jack Smith from scratch and sold it to Microsoft for $437M - adversity into opportunity."}, {"name": "Dr. G. Venkataswamy (Aravind)", "crux": "Applied McDonald's service-efficiency model to eye surgery; paying patients subsidise the poor; Aurolab low-cost lenses exported to 160+ countries - business model innovation."}, {"name": "Oprah Winfrey", "crux": "Grew up in abject poverty (potato-sack dresses) to a $3.5B media empire."}, {"name": "Andrew Carnegie", "crux": "Childhood factory worker who built Carnegie Steel and became a great philanthropist."}, {"name": "John D. Rockefeller", "crux": "Son of a travelling salesman, sold candy as a kid, founded Standard Oil."}, {"name": "Steve Jobs", "crux": "Dropout who lived on temple meals, pioneered the microcomputer revolution; Apple over $3.2T."}, {"name": "Camlin vs Doms; VIP vs Safari", "crux": "Newer first-generation players (Doms, Safari under Sudhir Jatia) overtook legacy firms in market value - first-gen founders can beat incumbents."}, {"name": "Theranos and Byju's", "crux": "Examples that deceptive or unscrupulous founders eventually fail."}], "keyTerms": [{"term": "Bootstrapping", "def": "Funding a venture from personal savings, credit cards, friends and family and sweat equity rather than external investors."}, {"term": "Sweat equity", "def": "Non-monetary contribution by owners or employees, often compensated with stock to align risk and reward."}, {"term": "Calculated risk", "def": "Evaluated, managed risk taken to pursue opportunity, as opposed to loving risk."}, {"term": "Premature scaling", "def": "Growing too much too soon before foundations are ready; a leading cause of failure."}, {"term": "E-Myth personalities", "def": "Entrepreneur (future), Manager (past), Technician (present)."}], "examAnswerTips": ["State the myth, then the reality with a number or source (80% bootstrapped, <1% VC-backed, GEM ages 18-64, Fortune 500 life 61 to 15 years).", "Back each with an example: Murthy's $250, Mittal's Rs 20,000, Dhirubhai, Hotmail.", "For how much capital to raise: bootstrapping first, VCs costlier and risk-averse, validate before raising, funding is only fuel.", "For conventional wisdom questions use the last three myths (great product, fast scaling, funding)."], "quiz": [{"q": "What percentage of new businesses are backed by VCs per the lecture?", "options": ["Less than 1%", "About 10%", "About 30%", "Over 50%"], "answer": 0, "why": "Myth 11."}, {"q": "In the E-Myth, the Manager lives in the:", "options": ["Future", "Past", "Present", "None"], "answer": 1, "why": "Entrepreneur future, technician present."}, {"q": "Narayana Murthy started Infosys with:", "options": ["$250 borrowed from his wife", "Rs 20,000 from his father", "VC funding", "Bank loan"], "answer": 0, "why": "Slide 11."}, {"q": "GEM 2017-18 found early-stage entrepreneurship:", "options": ["Concentrated under 30", "Evenly spread across 18-64", "Mostly over 50", "Mostly men"], "answer": 1, "why": "Myth 6."}, {"q": "Why do slides say entrepreneurs are NOT risk lovers?", "options": ["They avoid all risk", "They take calculated risks and see opportunity where others see risk", "Investors bear the risk", "They prefer stable jobs"], "answer": 1, "why": "Myth 2."}, {"q": "Average life of Fortune 500 companies has fallen from 61 years to about:", "options": ["40", "25", "15", "5"], "answer": 2, "why": "Projected 12 by 2027."}, {"q": "Aravind Eye Care emulated whose service-efficiency model?", "options": ["Toyota", "McDonald's", "Amazon", "Walmart"], "answer": 1, "why": "Slide 14."}, {"q": "Reality for 'Funding equals success':", "options": ["Funding is only fuel; execution and value drive success", "More funding always wins", "Funding is unnecessary", "VCs ensure success"], "answer": 0, "why": "Slide 34."}], "slug": "L04_Myths_Realities", "excluded": "Syllabus up to slide 35; later slides excluded."}, {"id": "L05", "title": "Why Startups Fail", "oneLiner": "Data-backed causes of startup failure (no market need, running out of cash, founder disharmony, premature scaling, chasm, neglected business process) and how to avert them, with Nokia, BlackBerry, Byju's, Iridium, AskMe and others.", "examRelevance": "Very high: past papers ask about problems at the chasm, actions a professional CEO takes to scale, how much capital to raise, co-founder team size, and premature scaling. Expect case questions applying the valley of death, chasm remedies and CB Insights failure reasons.", "sections": [{"heading": "Overview", "points": ["Failures follow patterns; many are avoidable through planning, listening to customers, learning from mistakes and respecting established knowledge.", "CB Insights: 70% of tech startups fail, around 20 months after first financing (avg ~$1.3M raised); 483 post-mortems studied (2024).", "In India 70% failed after raising about Rs 10 cr and 20 months; 97% of seed/crowdfunded consumer hardware startups die.", "Munger: know where you will die so you never go there - learn from others' failures instead of 50,000 experiments (Edison)."]}, {"heading": "Top failure reasons (CB Insights)", "points": ["42% no market need; 29% ran out of cash; 23% founder disharmony; 19% outcompeted.", "Usually multiple reasons; real causes hard to uncover.", "Failure data can mislead: acquisitions at lower valuation (Tapzo) or strategic exits (Ofo, eBay India) are counted as failures."]}, {"heading": "No market need / product-market fit", "points": ["Product-market fit: degree to which a product satisfies customer need and aspiration vs competitors.", "Typical death path: idea, build, try to sell, nobody buys, run out of money, die.", "Talk to customers before building; validate early and continuously; separate must-have from nice-to-have.", "'Life's too short to build something nobody wants' - Ash Maurya."]}, {"heading": "Running out of cash and the valley of death", "points": ["Running out of cash (29-38%): poor financial planning, not anticipating negative cash flow, not growing fast enough, losing investor appeal.", "Valley of death: early years (1-3) when startup cannot generate cash or raise funds to cover negative cash flow; up to 90% fail here.", "Investors prefer a validated prototype or proven business model.", "Cash flow is king (low margin, high payroll, long sales lag = poor cash flow)."]}, {"heading": "Product adoption curve and the chasm (Geoffrey Moore)", "points": ["Innovators 2.5%, early adopters 13.5%, early majority 34%, late majority 34%, laggards 16%.", "Early adopters tolerate beta defects; early majority need validation, value for money, and are averse to experiments.", "Chasm arises because startups are unprepared for hyper-growth: logistics, manpower, inputs, storage, BPM, marketing, service, collections.", "Also lack of planning, especially funds for growth; a professional CEO experienced in growth is essential but not adequate."]}, {"heading": "Chasm remedies (actions to scale)", "points": ["Achieve product perfection and product-market fit before targeting early majority.", "Plan early and pre-emptively arrange all resources.", "Prepare projected cash flow statements and arrange funds promptly.", "Hire manpower ahead of growth.", "Hire a professional CEO experienced in taking a company through the growth phase."]}, {"heading": "Team and focus", "points": ["'Individuals don't build great companies, teams do' (Suster). One-person teams are a failure cause.", "Sam Altman: 20 most valuable companies have at least two co-founders; 2-3 co-founders work best.", "Cover the startup triangle: designer, engineer, marketer.", "Lack of focus: stop coffees, needless networking, advisor boards, unproven partnerships, PR and conferences before product-market fit.", "As business grows founders must hire, train and empower managers to do founders' jobs."]}, {"heading": "Premature scaling", "points": ["Too much, too soon; up to 70% of startups scale too early, affecting up to 90% of failed ones (Startup Genome).", "Sequence: problem-solution fit (big problem, enough people, will pay), then product-market fit, then channel fit (lower CAC, retention).", "Scale only when customer acquisition cost is lower than lifetime value."]}, {"heading": "Business process, people and entrepreneurial essence", "points": ["Neglected business process can be fatal even with great idea, product and team (Zilingo); one weak pillar destabilises.", "BPM: identifies process problems, accelerates time to market, improves cost, quality, customer satisfaction, risk and compliance.", "Value people: understand, hear, empower, teach them; Nadella's empowering culture took Microsoft from $45 to $512 per share.", "Entrepreneurial essence: customer-centric innovation, no complacency, agility, calculated risk, empowering leadership.", "Unfair advantage types: insider information, network effects, personal authority, proprietary tech. Asymmetric model: commoditise complements to undercut rivals' core revenue."]}], "cases": [{"name": "Nokia", "crux": "Held 40% global share in 2007 (once 80%) with strong brand loyalty, but missed the shift from phone features to apps and entertainment; lost entrepreneurial essence."}, {"name": "BlackBerry (RIM)", "crux": "Pioneered mobile email, peaked at $80B+ (2008) and 41M subscribers, then lost to iPhone/Android touch and app ecosystems; pivoted to enterprise software and cybersecurity (~$2B) - first-mover advantage is fragile, reinvention possible."}, {"name": "Microsoft under Satya Nadella", "crux": "Empowering people and culture lifted share price from $45 to $512."}, {"name": "Google vs Newspapers", "crux": "Asymmetric business model: free content and ads monetised elsewhere undermines competitors' primary revenue."}, {"name": "Byju's", "crux": "Strong content, adaptive learning and global reach, acquisitions (Aakash, WhiteHat Jr, Osmo, Epic); failed through unethical sales, financial mismanagement, fudged accounts, unpaid TDS, aggressive marketing, late filings."}, {"name": "AskMe Group (Getit)", "crux": "Folded in 2016 due to lack of focus, needless acquisitions, weak tech, inconsistent strategy, cash crunch (cash loss 53 to 300 cr) and a single investor, plus founder-investor disharmony and dishonesty."}, {"name": "Iridium", "crux": "$6B satellite phone service (1998) assumed anywhere-to-anywhere calling would sell; bankrupt in 9 months due to high cost, bulky handsets, poor indoor reception; sold for $35M - no product-market fit and wrong timing. Successors: OneWeb, Starlink, Kuiper."}, {"name": "Just Buy Live", "crux": "Indian B2C e-commerce raised $120M but failed on an unscalable model and negative cash flow."}, {"name": "Airware", "crux": "Drone pioneer burned $118M; market matured slower than expected and it ran out of runway - timing a market transition is hard."}, {"name": "Aerion", "crux": "Despite an $11.2B order book and $1B in development, ran out of funds by not raising early enough."}, {"name": "Lyneir Richardson", "crux": "Grew revenue $0.6M to $7M but low margins, high payroll and long sales lag killed cash flow: cash flow is king."}, {"name": "Tapzo, Ofo, eBay India", "crux": "Counted as failures though they were acquisitions or strategic exits - failure data can be misleading."}, {"name": "Zilingo", "crux": "Example of fatal neglect of business process."}], "keyTerms": [{"term": "Valley of death", "def": "Early phase (years 1-3) with negative cash flow where startups cannot generate cash or raise funds; most fail here."}, {"term": "Chasm", "def": "Gap between early adopters and early majority (Moore) where startups fail to handle hyper-growth and stricter customer needs."}, {"term": "Product-market fit", "def": "Degree to which a product satisfies customers' needs and aspirations versus competitors."}, {"term": "Premature scaling", "def": "Scaling hiring, spend and growth before problem-solution and product-market fit; too much too soon."}, {"term": "Channel fit", "def": "Stage where acquisition costs fall and retention rises so the business can be profitable."}, {"term": "CAC vs LTV", "def": "Scale only when customer acquisition cost is below customer lifetime value."}, {"term": "Startup triangle", "def": "Designer, engineer and marketer skill coverage in a founding team."}, {"term": "Unfair advantage", "def": "Hard-to-copy internal strength: insider info, network effects, personal authority, proprietary tech."}, {"term": "Asymmetric business model", "def": "Using a loss-leader or commoditised complement to make a competitor's main revenue source irrelevant."}, {"term": "Business Process Management", "def": "Discipline of designing and improving how work is done to raise efficiency, quality and customer satisfaction."}], "examAnswerTips": ["For chasm questions: explain adoption curve percentages, contrast early adopters vs early majority, list unpreparedness items, then the five remedies.", "For professional CEO actions to scale: product perfection, pre-emptive resources, projected cash flow and funds, hire ahead, process (BPM), empower managers.", "For capital/funding: plan negative cash flow through the valley of death, raise early (Aerion, Airware), but avoid premature scaling and burn (Nasty Gal-style).", "For co-founders: 2-3 co-founders, startup triangle, cite Sam Altman and Suster; 23% failures from disharmony (AskMe).", "Always quote 42/29/23/19 and an example per reason (Iridium, Aerion, AskMe)."], "quiz": [{"q": "In Moore's adoption curve, early adopters make up:", "options": ["2.5%", "13.5%", "34%", "16%"], "answer": 1, "why": "Innovators 2.5, early adopters 13.5, majorities 34 each, laggards 16."}, {"q": "Which is NOT a remedy for crossing the chasm?", "options": ["Prepare projected cash flow", "Hire experienced professional CEO", "Scale marketing before product perfection", "Hire manpower ahead of growth"], "answer": 2, "why": "Product should gain perfection first."}, {"q": "Iridium failed mainly because:", "options": ["No funding", "High cost, bulky devices, poor indoor reception - no product-market fit", "Founder fraud", "Competition from Starlink"], "answer": 1, "why": "Sold for $35M after $6B."}, {"q": "Sam Altman suggests startups work best with:", "options": ["1 founder", "2-3 co-founders", "5+ co-founders", "No co-founders"], "answer": 1, "why": "Slide 57."}, {"q": "Correct order before scaling:", "options": ["Channel fit, PMF, problem-solution", "Problem-solution fit, product-market fit, channel fit", "PMF, channel fit, problem-solution", "Funding, hiring, PMF"], "answer": 1, "why": "Slide 60."}, {"q": "When should a startup step on the gas and scale?", "options": ["After first funding", "When CAC is lower than LTV", "When competitors scale", "After hiring a board"], "answer": 1, "why": "Slide 60."}, {"q": "Aerion's failure was attributed to:", "options": ["No orders", "Not raising funds early enough", "Bad product", "Founder disharmony"], "answer": 1, "why": "Had $11.2B order book."}, {"q": "The valley of death is the phase where:", "options": ["Startups IPO", "Negative early cash flow cannot be covered by revenue or funding", "Late majority adopt", "Founders exit"], "answer": 1, "why": "Up to 90% fail here."}, {"q": "Which is a type of unfair advantage per slides?", "options": ["Network effects", "Lower prices", "Bigger office", "More ads"], "answer": 0, "why": "Also insider info, personal authority, proprietary tech."}], "slug": "L05_Why_Startups_Fail", "excluded": "Crossed-out slides 10, 20, 25, 26, 50–52 excluded; syllabus up to slide 65."}, {"id": "L06", "title": "Business Model Canvas and Value Proposition", "oneLiner": "How Osterwalder's 9-block Business Model Canvas describes how a venture creates, delivers and captures value, with the Value Proposition and Customer Segment at its heart.", "examRelevance": "Expect questions on advantages/criticism of the BMC, listing all 9 blocks, and explaining specific blocks such as Channels (5-6 functions) and Key Partners (types). A 'draw the BMC for a taxi aggregator / your idea' or 'value proposition canvas' question is likely; Iridium is the go-to failure example.", "sections": [{"heading": "Business model vs business plan", "points": ["Business model (Osterwalder): the rationale of how an organization creates, delivers and captures value.", "Prof's broader definition: a business opportunity with all its features - risks, customer segment, market structure, competition, feasibility, profitability, growth, legal tenability and execution plan.", "Constructing/modifying a business model = business model innovation, part of business strategy.", "Business plan: detailed execution document - SWOT, team skills, operations, marketing plan, financial projections.", "Key line: a business model is how a business operates; a business plan describes the business and outlines its strategy."]}, {"heading": "The canvas: 9 building blocks", "points": ["Proposed by Alexander Osterwalder (Business Model Generation, 2010, with Pigneur).", "Blocks: Key Partners, Key Activities, Key Resources, Value Proposition, Customer Relationships, Channels, Customer Segments, Cost Structure, Revenue Streams.", "Heart of the canvas: Value Proposition and Customer Segment - customers pay for value, and that gives profit.", "Left side (partners, activities, resources, cost) = efficiency / how value is created; right side (relationships, channels, segments, revenue) = how value is delivered and captured."]}, {"heading": "Value Proposition block", "points": ["Sum total of features/benefits of a product or service that customers perceive as value for money in the targeted segment.", "Gives reasons why customers buy from you over competitors; customers weigh feature bundle and price vs competing products.", "Benefit list: quality, efficacy, usefulness, esteem, ease of use/installation, safety, reliability, cost, warranty, aesthetics, delivery, after-sale service, return policy, resale value, shelf-life etc.", "Must be so clear that advantages need no explanation - confused customers buy others' products. State how you solve the problem better than competition.", "Not a value proposition: features/services customers don't value, vanity metrics, anything not helping the business."]}, {"heading": "Value Proposition Canvas (product-market fit)", "points": ["Customer side: Customer Jobs, Pains, Gains.", "Value side: Products and Services, Pain Relievers, Gain Creators.", "Fit between the two sides = product-market fit.", "Taxi example: jobs (find taxi, pay, arrive on time); pains (overcharging, long wait, unsafe driver); relievers (rating, visual map, instant booking, no cash); gains (fair price, loyalty points, schedule trip)."]}, {"heading": "Customer Segment block", "points": ["Market segmentation: dividing a broad population into sub-groups sharing characteristics - needs, interests, lifestyles, demographics.", "Segment should promise a profitable relationship with growth potential.", "Groups are separate segments if needs/behaviour are unique and they will pay extra to justify the extra cost of serving them.", "Sharper focus = smaller segment = more niche marketing."]}, {"heading": "Channels and Customer Relationships", "points": ["Channels: how a company communicates with and reaches its segments to deliver the value proposition.", "Channel functions: create awareness; help customers evaluate the VP; enable easy purchase; deliver conveniently; after-sale support; allow return/exchange.", "Some canvases put 'Unfair advantage' here: real competitive advantage is hard to copy or buy.", "Customer Relationships: building and maintaining long-term relationships; motivations - acquisition, retention, growth, profit from customer lifetime value."]}, {"heading": "Revenue Streams and Cost Structure", "points": ["Revenue: cash generated from each segment; if customers are the heart, revenue streams are the arteries.", "Key question: for what value is each segment truly willing to pay? Covers pricing model, gross margin, burn rate/profit, lifetime value, growth strategy.", "Cost Structure: all costs to create and deliver value, maintain relationships and generate revenue (raw material, rent, salaries, hosting, ads, depreciation, interest, R&D, royalty).", "Cost concepts: fixed vs variable cost, cost minimization, economies of scale, value-driven cost management."]}, {"heading": "Key Resources, Activities, Partners", "points": ["Key Resources: most important assets to make the model work - physical, intellectual (patents, brands, data), human, financial; owned or obtained from partners.", "Example: e-car maker needs batteries; battery maker needs lithium, cobalt, nickel, graphite etc.", "Key Activities: the most important things the firm must do (taxi example: manage booking, optimize vehicle logistics, maintain records).", "Key Partners: network of suppliers, resource providers, facilitators; alliances optimize the model, reduce risk, acquire resources.", "Partner types: key suppliers, strategic alliances, joint ventures, distribution/logistics, technology partners, investors. Mostly outside partners, not co-founders."]}, {"heading": "Criticism of BMC", "points": ["No reference to exogenous (external) forces.", "Focuses on economic value, not environmental and social value.", "Silent on creating competitive advantage, entry barriers, scaling.", "Overly simplistic and narrow given diverse business challenges."]}], "cases": [{"name": "Iridium (Motorola tech)", "crux": "Launched Nov 1998 with US$6 bn assuming people would want anywhere-to-anywhere calling; bankrupt Aug 1999 - calls expensive, bulky handset, poor indoor reception, needed all 66 satellites. Sold for US$35 mn. Failed for ignoring value proposition: affordability, usefulness, readiness of supporting tech."}, {"name": "Taxi aggregator BMC (class worked example)", "crux": "Segments: commuters, working people, tourists, 18-70; VP: easy booking/payment, safety, transparent rate, no waiting; Channels: app, call centre, Google ads; Revenue: pay per ride, ads on app/taxis; Partners: car owners, wallet firms, tech/hardware providers, driver association."}, {"name": "Value proposition statements", "crux": "Uber - The Smartest Way to Get Around; Apple iPhone - The Experience is the Product; Digit - Save Money Without Thinking About It; CrazyEgg - Website Behavior Tracking at an Unbeatable Price."}], "keyTerms": [{"term": "Business model", "def": "Rationale of how an organization creates, delivers and captures value (Osterwalder)."}, {"term": "Business plan", "def": "Document detailing execution of a business model: SWOT, team, operations, marketing, financial projections."}, {"term": "Value proposition", "def": "Sum total of product/service features customers perceive as value for money; why they buy you over competitors."}, {"term": "Market segmentation", "def": "Dividing a population into sub-groups with shared needs, interests, lifestyles or demographics."}, {"term": "Channels", "def": "How the firm communicates with and reaches segments to deliver the VP - awareness through after-sale."}, {"term": "Product-market fit", "def": "Match between customer jobs/pains/gains and the offering's pain relievers/gain creators."}, {"term": "Lifetime value", "def": "Total profit from a customer over the relationship; motive behind customer relationship building."}, {"term": "Business model innovation", "def": "Process of constructing and modifying a business model."}], "examAnswerTips": ["Always name all 9 blocks and say VP + Customer Segment are the heart; a quick sketch of the canvas earns marks.", "Advantages of BMC (derive from slides): one-page holistic view of creating/delivering/capturing value, links VP to segments, shows cost vs revenue, easy to modify (business model innovation). Then add the 4 criticisms for balance.", "For Channels, list the 6 functions in order: awareness, evaluation, purchase, delivery, after-sale support, return/exchange.", "For Key Partners, define then list types (suppliers, strategic alliances, JVs, distribution/logistics, technology, investors) and the why (optimize, reduce risk, acquire resources); quote taxi example partners.", "Quote Iridium for value-proposition failure and the taxi aggregator for a filled canvas/VP canvas."], "quiz": [{"q": "Which two blocks form the heart of the Business Model Canvas?", "options": ["Key Partners and Key Resources", "Value Proposition and Customer Segment", "Revenue Streams and Cost Structure", "Channels and Customer Relationships"], "answer": 1, "why": "Slides say the heart is VP and Customer Segment."}, {"q": "Osterwalder defines a business model as the rationale of how an organization...", "options": ["plans, finances and audits value", "creates, delivers and captures value", "segments, prices and sells products", "raises, spends and returns capital"], "answer": 1, "why": "Creates, delivers and captures value."}, {"q": "Which is NOT listed as a function of the Channels block?", "options": ["Creating awareness of the VP", "Facilitating easy purchase", "Supplying raw materials", "Allowing return or exchange"], "answer": 2, "why": "Supplying inputs belongs to Key Partners."}, {"q": "Iridium filed for bankruptcy roughly how long after launch?", "options": ["Nine months", "Three years", "Five years", "Eighteen months"], "answer": 0, "why": "Launched Nov 1998, bankrupt Aug 1999."}, {"q": "In the Value Proposition Canvas, 'rating system' and 'visual map' for a taxi app are examples of:", "options": ["Customer jobs", "Gains", "Pain relievers", "Key resources"], "answer": 2, "why": "They relieve pains like unsafe drivers and long waits."}, {"q": "Which is a criticism of the BMC in the slides?", "options": ["Too much focus on social value", "No reference to exogenous forces", "Too complex for startups", "Ignores customers"], "answer": 1, "why": "Criticisms: no exogenous forces, only economic value, silent on moats/scaling, simplistic."}, {"q": "'If customers are the heart of a business model, ___ are its arteries.'", "options": ["Channels", "Key Partners", "Revenue Streams", "Key Activities"], "answer": 2, "why": "Revenue streams are the arteries."}, {"q": "Patents, brands and customer databases are which type of key resource?", "options": ["Physical", "Financial", "Human", "Intellectual"], "answer": 3, "why": "Intangible assets are intellectual resources."}], "slug": "L06_BMC_Value_Proposition", "excluded": "Crossed-out slides 4, 5, 8, 9, 18, 22–24, 49, 50, 53 excluded."}, {"id": "L07", "title": "Lean Startup and MVP", "oneLiner": "Product adoption and crossing the chasm, then Eric Ries's Lean Startup (lean + agile): hypotheses, MVP, build-measure-learn, pivot and charging early.", "examRelevance": "Classic questions: value hypothesis vs growth hypothesis, 'state the hypothesis and leap of faith' (Nick Swinmurn shoe example), what is an MVP and how to build one, pivot vs persevere, waterfall vs agile. Adoption curve percentages and crossing the chasm also likely.", "sections": [{"heading": "Product adoption curve (Moore, Crossing the Chasm)", "points": ["Innovators 2.5%: adventuresome, educated, risk takers.", "Early adopters 13.5%: segment leaders, knowledgeable, ok with risk.", "Early majority 34%: socially active, calculated risk, need lots of validation.", "Late majority 34%: want validation and revalidation, value for money, averse to experiments.", "Laggards 16%: complacent, risk averse, wait until it is a household product.", "Funding map: bootstrap/seed (innovators), Series A, B, C, then Series D or IPO (late majority/laggards)."]}, {"heading": "Crossing the chasm", "points": ["Diffusion-of-innovation concept, essential to tech entrepreneurship.", "Early adopters are tech enthusiasts/visionaries; early majority are pragmatists with different expectations - stimulation that worked for visionaries fails, creating a chasm.", "To cross: plan growth ahead, set up infrastructure and manpower, deep product understanding, positioning, marketing strategy, right distribution channel, attractive pricing."]}, {"heading": "Lean Startup = Lean + Agile", "points": ["Lean (manufacturing): eliminate waste, build only what creates value, continuous improvement (Kaizen). Waste = resources that add no incremental value to customers.", "Agile (software): iterative incremental development, rapid customer feedback loops, flexibility.", "Eric Ries combined lean waste-elimination with agile validated learning; adds charging early and dropping non-value features.", "A scientific approach to continuously test hypotheses and adapt before it is too late."]}, {"heading": "Waterfall vs Agile", "points": ["Waterfall: linear, sequential - requirements, design, implementation, verification, maintenance; release and validate only at the end, so resources, risk and money are sunk before validation.", "Agile: non-linear, repeated validation with customers (validated learning); launch after customer acceptance.", "Cost of correcting quality issues rises downstream; fix at the earliest point.", "Agile traits: iterative, collaborative, customer-centric, adaptable, transparent, empowered self-organizing teams, short sprints (2-4 weeks), minimal documentation."]}, {"heading": "Ries: five key constituents", "points": ["Lean thinking: small batches, just-in-time, faster cycle times.", "Measure progress through validated learning.", "Productivity: make what people like and pay a profitable price for, fast and economically.", "Build-measure-learn loop: a steering wheel instead of assumptions; tells you if/when to pivot.", "Charge early: a paying customer is real validation and helps cash flow."]}, {"heading": "Hypotheses, steering and pivot", "points": ["Experiment with two hypotheses: value hypothesis (does the product deliver value customers want/pay for) and growth hypothesis (how new customers will discover and adopt it).", "Leap-of-faith assumptions: the riskiest beliefs the venture rests on, to be tested first.", "Steer: minimize total time through the loop, use MVP, set learning milestones.", "Pivot: course correction based on learning; pivot early if you must. Vanity metrics prevent pivoting.", "Ask: what if the user doesn't care about the design the way we do?"]}, {"heading": "Validation and MVP", "points": ["Validation: assessing likely product-market fit by user testing; early test of your hypothesis for faster, de-risked decisions.", "MVP: product with essential features only (e.g. landing page, no aesthetics) that customers can use and give feedback on.", "Creating MVP: find the most critical feature that lets customers judge your VP; understand user stories/pain points.", "Watching people use a product beats asking what they would do.", "Charge early: if customers pay for the MVP, that is the real validation."]}, {"heading": "Build-Measure-Learn and metrics", "points": ["Build: minimum key features so customers grasp usefulness. Measure: feedback on usability, experience, per-feature performance. Learn: test product-market-fit hypothesis, then pivot or persevere.", "Useful metrics are the 3 As: Actionable (clear cause-effect), Accessible (understandable), Auditable (reflects real performance).", "SMART objectives: Specific, Measurable, Assignable, Realistic, Time-bound."]}], "cases": [{"name": "Nick Swinmurn - online shoes", "crux": "Frustrated at not finding shoes in stores. Hypothesis: people have limited choice in a store. Leap of faith: given thousands of designs, most people would not mind buying shoes online without trial. Piloted via an MVP instead of buying stock, logistics and staff. (Company is Zappos; the photograph-shoes-in-stores detail is not on the slide.)"}, {"name": "School hands-on learning content (hypothetical MVP)", "crux": "User story: schools lack infrastructure for practical experiments. Instead of a full course, build one module/a few tools, test with a batch of students for engagement, ease and retention, then decide - postponing big investment."}, {"name": "IIT Kharagpur drip emitter", "crux": "Three-component emitter (5 g plastic, Rs 5-12) re-engineered into a single-component one (0.95 g, about Rs 0.25), plus a biodegradable wooden version - lean waste elimination in practice."}, {"name": "SIP compounding table", "crux": "Rs 25,000/month at 12% for 40 years gives about Rs 29.7 crore vs Rs 15.9 crore at 10% - small rate or time differences compound hugely (illustrates accelerating change)."}], "keyTerms": [{"term": "Value hypothesis", "def": "Tests whether the product actually delivers value customers want and will pay for."}, {"term": "Growth hypothesis", "def": "Tests how new customers will discover and adopt the product (how it will spread)."}, {"term": "Leap-of-faith assumption", "def": "The riskiest core belief the venture depends on; test it first with an MVP."}, {"term": "MVP", "def": "Minimum Viable Product: essential-feature version used to get real customer feedback and validate hypotheses."}, {"term": "Pivot", "def": "Course correction in strategy based on validated learning; do it early if needed."}, {"term": "Validated learning", "def": "Learning proven through customer data from build-measure-learn iterations."}, {"term": "Vanity metrics", "def": "Flattering numbers that do not inform decisions and prevent pivoting."}, {"term": "Chasm", "def": "Gap between visionary early adopters and pragmatic early majority."}, {"term": "Kaizen", "def": "Continuous improvement, a lean principle."}], "examAnswerTips": ["For value/growth hypothesis questions: define both, then apply to a class example - Nick Swinmurn: value = people will buy shoes online without trial if choice is huge; growth = word of wide choice spreads and buyers keep coming online.", "'State hypothesis and leap of faith' - quote the slide wording: hypothesis 'people have limited choices when they visit a store'; leap of faith 'given thousands of designs, most people would not mind buying online'.", "MVP answers: definition, how to create (critical feature, user story), example (school module or shoe pilot), and 'charge early = real validation'.", "Draw the Build-Measure-Learn loop and end with 'pivot or persevere'; mention vanity metrics prevent pivoting.", "For adoption curve, write all five groups with 2.5/13.5/34/34/16 and the chasm between early adopters and early majority."], "quiz": [{"q": "What percentage of consumers are 'early adopters' on the adoption curve?", "options": ["2.5%", "13.5%", "34%", "16%"], "answer": 1, "why": "Innovators 2.5, early adopters 13.5, early/late majority 34 each, laggards 16."}, {"q": "The 'chasm' lies between:", "options": ["Innovators and early adopters", "Early adopters and early majority", "Late majority and laggards", "Early and late majority"], "answer": 1, "why": "Visionaries vs pragmatists."}, {"q": "Lean Startup combines:", "options": ["Six Sigma and waterfall", "Lean manufacturing and Agile", "Design thinking and BMC", "Kaizen and IPO"], "answer": 1, "why": "Ries combined lean waste elimination with agile validated learning."}, {"q": "In Nick Swinmurn's case, the leap of faith was that:", "options": ["Stores would stock more designs", "Given thousands of designs, people would buy shoes online without trial", "Investors would fund logistics", "Shoes could be made cheaper"], "answer": 1, "why": "Exactly as stated on the slide."}, {"q": "According to the slides, what is the 'real validation' of a hypothesis?", "options": ["Positive survey responses", "A paying customer", "Media coverage", "Number of app downloads"], "answer": 1, "why": "Charge early - paying customers validate."}, {"q": "Which prevents pivoting according to Ries?", "options": ["Charging early", "Vanity metrics", "Short sprints", "Learning milestones"], "answer": 1, "why": "Slide: vanity metrics prevent pivoting."}, {"q": "The 3 As of useful metrics are:", "options": ["Actionable, Accessible, Auditable", "Accurate, Agile, Assignable", "Aligned, Audited, Actual", "Achievable, Accessible, Agile"], "answer": 0, "why": "Actionable, accessible, auditable."}, {"q": "Typical agile sprint length in the slides:", "options": ["1-2 days", "2-4 weeks", "3-6 months", "1 year"], "answer": 1, "why": "Sprints typically 2-4 weeks."}, {"q": "In the waterfall model, validation happens:", "options": ["Continuously", "After every sprint", "Only at release, after resources are spent", "Before design"], "answer": 2, "why": "Linear process: release and validate at the end."}], "slug": "L07_Lean_Startup", "excluded": "Crossed-out slides 32–37 excluded."}, {"id": "L08", "title": "Entrepreneurial Qualities, Vision and Mission", "oneLiner": "Traits of successful entrepreneurs and the hierarchy of vision, mission, goals, objectives, strategies and core values.", "examRelevance": "Likely: define/differentiate vision vs mission (with ITC, Google, Netflix examples), build a vision-mission-goal-objective-strategy chain for a venture, or list/explain key entrepreneurial qualities (internal locus of control, tolerance for ambiguity, knowing when to pivot).", "sections": [{"heading": "Mindset", "points": ["Leaving your comfort zone matters: fear limits achievement; everyone has the power to change.", "Embrace change and discipline; set long-term vision and short-term goals; craft strategies; improve constantly.", "Wayne Gretzky: go to where the puck is going to be, not where it is - anticipate change.", "Hard work is indispensable but not enough; successful entrepreneurs spot opportunity in adversity and act with confidence."]}, {"heading": "Vision", "points": ["Where the company wants to be / what it aspires to accomplish in the long run; relates to dream and passion.", "Business Dictionary: aspirational description of long-term achievement, a clear guide for current and future actions.", "Sets direction for business planning; guides designs but is not the design (Musk: Mars, not the spacecraft).", "Founders must articulate and share it - a shared vision is a hallmark of business success."]}, {"heading": "Mission", "points": ["What the company does, why it exists, whom it serves, and why customers should see it as different or preferable.", "Explains purpose, defines culture, values, ethics and fundamental goals for stakeholders.", "Keeps employees and stakeholders (distributors, suppliers, investors, partners) aligned and focused; encourages innovation.", "Focuses on the present, whereas vision is the long-term future state.", "Google mission dissected: purpose, scope, target audience, value proposition, distinguishing factor - a compass for the organization."]}, {"heading": "Vision to strategy hierarchy", "points": ["Vision: broad aspirational long-term future state.", "Mission: present purpose - what, whom, how.", "Goals: broad, long-term, usually qualitative outcomes.", "Objectives: specific, measurable, short-to-medium-term steps toward goals.", "Strategies: plans/approaches designed to achieve objectives. Each level builds on the one above."]}, {"heading": "Core values", "points": ["Fundamental principles guiding behaviour, decisions and interactions; shared beliefs defining identity and culture.", "Support the vision; on a light note, define how the company behaves; employees uphold them with all stakeholders.", "Examples: empathy, quality, ethics, trust, honesty, accountability, transparency, integrity-type values, diversity, creativity, collaboration, safety, growth."]}, {"heading": "Leadership and people skills", "points": ["Unquestionable honesty and integrity; effective communication; motivate towards a common goal; take responsibility, give credit; no excuses.", "Educate, delegate, empower subordinates; foster innovation; ready for adversity and failure; charismatic.", "Charisma (Cambridge): special power to influence others and attract attention/admiration; traits include confidence, patience, keeping word, listening twice as much as talking.", "People skill elements (HBR Entrepreneur's Handbook): leadership, persuasion, influence, network building, exciting people with vision, strong ethics/governance, respecting laws and others' ownership."]}, {"heading": "Work style (HBR)", "points": ["Goal oriented, comfortable with uncertainty, self-challenging, prefer being own boss, never complacent.", "Driven to plan; experimental mindset - start small and move past failures; persevere in adversity.", "Always seek a better way; able to close a deal; willing to listen, trust and take advice."]}, {"heading": "Key entrepreneurial qualities", "points": ["Experimental mindset (test, fail, pivot rapidly) and customer obsession (empathy, solving pain points).", "Empathetic to customers and employees: feel the customer's pain; do employees' tasks occasionally; make them feel ownership.", "Financially savvy: understand cost structure, revenue model, cash flow, burn rate; poor fund management frequently causes failure.", "Internal locus of control: believe they control outcomes, no blaming fate; external locus blames outside forces for failure and credits self for success.", "Tolerance for ambiguity: committed to goals yet open to mid-course correction amid uncertainty.", "Tenacious, persistent, self-disciplined (self-discipline is central to most traits), self-motivated, decisive and action oriented."]}, {"heading": "More qualities", "points": ["Accept failure as an option and learn from it; reasonably passionate - know when to pivot, not driven by emotion.", "Ability to sell (Mark Cuban); frugal - a lean way always exists; calculated risk takers.", "Knowledge-seeker; strong peer network; delegate; manage time and say no; seek help - help is synergistic.", "Systems thinker: business is a system of interacting parts within larger systems (Great Chinese Famine 1959-61 as a cautionary system-disruption example).", "Circumspect and confident (360-degree SWOT view); best promoter and relationship builder; prior exposure (startup work, family business, profit-centre head) helps.", "Founding team preferably more than one with complementary skills; many traits can be acquired."]}], "cases": [{"name": "Just Buy Live vs Udaan", "crux": "Both B2B e-distribution, same time. Just Buy Live raised US$100 mn in 2017, shut in 2018. Udaan (ex-Flipkart founders incl. IIT KGP's Amod Malviya) pivoted from logistics to B2B, valued US$11.5 bn, later down-round to US$1.8 bn (Jan 2024). Appeared too good to fail, failed quickly."}, {"name": "Jessica Alba - Honest company", "crux": "Couldn't find eco-friendly baby products (2009); Brian Lee rejected her first pitch. She refined products and pitch with feedback from friends, launched 17 products, re-pitched in 2012 and got funded; valued US$2 bn (2021). Lessons: loving criticism, know customers, believe in idea, persist."}, {"name": "Ankur Jain - Bilt", "crux": "Father rejected his idea in 2015; built Bilt (US$3.1 bn, May 2024) in a fiercely competitive market with one customer-centric differentiator."}, {"name": "Netflix vs Blockbuster", "crux": "Netflix began as DVD-by-mail but set a vision to reach every home via internet; Blockbuster clung to physical stores and went bankrupt in 2010 - power of vision."}, {"name": "Bill Gates / Elon Musk", "crux": "Gates: a PC in every home. Musk: humans living on Mars - vision guides design but is not the design."}, {"name": "ITC", "crux": "Vision: sustain position as one of India's most valuable corporations creating value for economy and stakeholders. Mission: enhance wealth-generating capability in a globalising environment delivering superior, sustainable stakeholder value."}, {"name": "Google mission", "crux": "Organize the world's information and make it universally accessible and useful - shows purpose, scope, audience, VP and distinguishing factor."}, {"name": "GenAI healthcare company (hierarchy example)", "crux": "Vision: tech integrated into life for better health; Mission: innovate tech for healthcare productivity; Goal: leading AI healthcare provider in a decade; Objective: +15% market share in 2 years; Strategy: hire best talent to build AI suite."}, {"name": "Jack Ma - Alibaba", "crux": "Rejected in 30 job applications and many college admissions; launched Alibaba in 1999, valued near US$500 bn in about 20 years - determination."}], "keyTerms": [{"term": "Vision", "def": "Aspirational long-term statement of what the organization wants to become or achieve."}, {"term": "Mission", "def": "Present-focused statement of what the company does, whom it serves, how, and why it is preferable."}, {"term": "Goals", "def": "Broad, long-term, usually qualitative outcomes."}, {"term": "Objectives", "def": "Specific, measurable short-to-medium-term steps toward goals."}, {"term": "Strategy", "def": "Plan or approach designed to achieve objectives."}, {"term": "Core values", "def": "Fundamental principles guiding behaviour and culture, supporting the vision."}, {"term": "Internal locus of control", "def": "Belief that one controls one's own outcomes, not fate or outside forces."}, {"term": "Tolerance for ambiguity", "def": "Ability to stay committed to goals while handling uncertainty and making mid-course corrections."}, {"term": "Systems thinking", "def": "Holistic view of how a system's parts interrelate and work within larger systems."}, {"term": "Charisma", "def": "Natural power to influence people and attract attention and admiration (Cambridge)."}], "examAnswerTips": ["Vision vs mission: vision = future/aspiration (where), mission = present/purpose (what, whom, how, why different). Quote ITC's pair or Google's mission, and Netflix vs Blockbuster.", "For a 'frame vision, mission, goal, objective, strategy for X' question, mirror the GenAI healthcare chain and make the objective numeric and time-bound.", "For qualities, pick 5-6 and attach a story: persistence (Alba, Jack Ma), pivoting (Udaan), customer-centric differentiator (Bilt), internal locus of control, tolerance for ambiguity.", "Mention that many traits can be acquired and a team with complementary skills is preferred."], "quiz": [{"q": "Which statement best describes a mission?", "options": ["Long-term aspirational future state", "What the company does, whom it serves and why it is preferable", "A measurable short-term target", "Shared beliefs of employees"], "answer": 1, "why": "Mission is present-focused purpose."}, {"q": "'To increase market share by 15% in the next two years' is a:", "options": ["Vision", "Mission", "Goal", "Objective"], "answer": 3, "why": "Specific and measurable = objective."}, {"q": "Which company refused to change and went bankrupt in 2010?", "options": ["Netflix", "Blockbuster", "Iridium", "Just Buy Live"], "answer": 1, "why": "Blockbuster vs Netflix."}, {"q": "People with an external locus of control tend to:", "options": ["Take responsibility for failure", "Blame outside forces for failures and credit themselves for success", "Believe they create their future", "Avoid risk entirely"], "answer": 1, "why": "Slide definition."}, {"q": "Udaan pivoted from:", "options": ["B2C to B2B", "Logistics to B2B", "Fintech to logistics", "Hardware to software"], "answer": 1, "why": "Pivoted from logistics company to B2B."}, {"q": "How many products did Jessica Alba launch at once against advice?", "options": ["1", "5", "17", "30"], "answer": 2, "why": "She launched 17 products."}, {"q": "Which order runs from broadest to most specific?", "options": ["Strategy, objective, goal, mission, vision", "Vision, mission, goals, objectives, strategies", "Mission, vision, objectives, goals, strategies", "Goals, vision, mission, strategies, objectives"], "answer": 1, "why": "Hierarchy on slide 14."}, {"q": "Who said 'I go to where the puck is going to be, not where it is'?", "options": ["Mark Cuban", "Wayne Gretzky", "Jack Ma", "Elon Musk"], "answer": 1, "why": "Hockey player Wayne Gretzky."}], "slug": "L08_Qualities_Vision_Mission", "excluded": "Syllabus up to slide 55."}, {"id": "L09", "title": "Cost-Volume-Profit and Break-Even Point Analysis", "oneLiner": "How to classify costs into fixed and variable, compute contribution, break-even point, margin of safety, target-profit volume, operating leverage and cost indifference point.", "examRelevance": "One full question is announced on Break-Even Point: expect cost classification of a list of items, a numeric BEP/contribution/margin-of-safety/profit calculation, and possibly a technology choice (cost indifference) or operating leverage discussion.", "sections": [{"heading": "Why BEP (uses)", "points": ["Minimum sales needed to reach profitable operation; profitability at different scales of operation.", "Select a business model among options, or test a model against market size.", "Scenario/sensitivity analysis for changes in selling price or cost structure (marginal cost and marginal revenue).", "Compare two technologies by cost structure; assess comfort under market distress.", "Estimate threshold price below which the project incurs a loss; decide minimum competitive price.", "Acts as a sales milestone for the team; gives margin of safety and risk; helps cost control and quick estimates."]}, {"heading": "Two ways to classify costs", "points": ["Direct cost: directly traceable to each product (raw materials, direct labour). Indirect cost: hard to allocate per product. Used for product costing.", "Fixed cost: not related to activity level; borne even with zero activity. Variable cost: proportional to level of operation. Used for BEP (company specific).", "Fixed cost per unit falls as production rises; variable cost per unit stays constant.", "Cost driver: a factor whose change causes a change in the cost of an activity; an activity can have several (e.g. fabric, tailor wages, buttons, machine hours, electricity, rent for a shirt)."]}, {"heading": "Classification rules to memorise (exam list)", "points": ["FIXED: depreciation, amortization, insurance, interest on long-term loan, audit fee, trade licence, fire safety, RoC registration fee, rent, salaries, annual renewal of export licence.", "FIXED (also): internet and data plan, web-hosting cost, cost of security around factory.", "VARIABLE: raw materials, consumables, wages, electricity bill, fuel, transportation, stationery, printing, packaging and delivery.", "VARIABLE (also): production bonus, travelling expenses, telephone bill, sales promotion, advertisement, maintenance, interest on short-term (working capital) loan.", "NOT A COST: income tax and dividend (appropriations of profit, never put in BEP cost).", "Semi-variable: insurance and maintenance. For exam: treat INSURANCE as FIXED and MAINTENANCE as VARIABLE.", "Salaries of permanent employees are fixed; wages of contractual workers are variable."]}, {"heading": "Semi-variable items explained", "points": ["Maintenance: scheduled/preventive part is fixed, need-based/trouble-shooting part is variable; treated as variable overall.", "Insurance: on fixed assets is fixed; on inventory of raw materials and finished goods is variable. Fixed share can be split by historical ratio or asset values.", "Interest on long-term loan (raised to create fixed assets) is fixed; interest on working capital/short-term loan is variable.", "Utilities like electricity and telephone are paid periodically but are not fixed in nature."]}, {"heading": "Contribution and BEP formulas", "points": ["Sales = Q x S; total variable cost = Q x V; total cost = Q x V + F; profit P = Q x S - (Q x V + F).", "Unit contribution (contribution margin) = S - V. Total contribution = total sales - total variable cost.", "BEP quantity = F / (S - V). All fixed cost is recovered out of contribution; after BEP each extra unit adds profit equal to unit contribution.", "Target-profit quantity = (F + target profit) / (S - V).", "BEP is where total revenue equals total cost: no profit, no loss."]}, {"heading": "Shirt (readymade garment) worked example", "points": ["Fixed costs per year: rent 1,20,000 + depreciation 15,000 + administrative overhead 5,00,000 = Rs 6,35,000.", "Material and labour per shirt: 400 + 20 + 10 + 100 = Rs 530 (20 shirts = Rs 10,600).", "Add consumables 15 + packaging 10 + transport/delivery/misc 20: total variable cost Rs 575 per shirt.", "Selling price Rs 800, so contribution margin = 800 - 575 = Rs 225 per shirt.", "BEP = 6,35,000 / 225 = 2,822.2, rounded up to 2,823 shirts. Selling 3,823 (1,000 beyond BEP) gives profit 1,000 x 225 = Rs 2,25,000.", "At planned sales of 5,000 shirts, margin of safety = 5,000 - 2,823 = 2,177 units."]}, {"heading": "Semi-variable repair and maintenance example", "points": ["Fixed: depreciation 20,000, insurance 5,000, repair and maintenance 5,000 = F Rs 30,000/yr. Variable per unit: R&M 0.50, material 9.50, labour and power 10.00 = V Rs 20.", "S = Rs 30, so BEP = 30,000 / (30 - 20) = 3,000 units.", "At 2,000 units: revenue 60,000, cost 30,000 + 40,000 = 70,000, loss Rs 10,000.", "For profit Rs 10,000: Q = (30,000 + 10,000) / 10 = 4,000 units, i.e. 1,000 units beyond BEP."]}, {"heading": "Multi-year table and class exercise", "points": ["Six-year table: fixed cost 955 each year; variable cost is 90% of sales; contribution = 10% of sales.", "Year 1 sales 5,000: contribution 500, loss 455. Year 6 sales 10,000: contribution 1,000, profit 45, so break-even is reached in the 6th year.", "Exercise: 500 units, sales 40,000 (S = 80), variable cost 15,000 (V = 30), F = 20,000. CM = 50; total contribution 25,000; BEP = 400 units.", "At 600 units: MoS 200 units, profit 600 x 50 - 20,000 = Rs 10,000. At 250 units: below BEP by 150 units, loss 250 x 50 - 20,000 = -Rs 7,500."]}, {"heading": "Margin of safety and graph", "points": ["Margin of safety = planned (or actual) sales minus BEP sales; amount by which sales can fall without causing loss.", "Shows how sensitive the present operation is to market fluctuation.", "Graph: fixed cost horizontal; total cost line V x Q + F starts at F; sales line S x Q from origin; intersection is BEP; loss zone left, profit zone right.", "Reducing variable cost lowers BEP (slides show 2,823 falling to about 1,823/1,500); raising fixed cost while cutting variable cost shifts BEP (e.g. to 2,500 or 2,700)."]}, {"heading": "Operating leverage", "points": ["Operating leverage: degree to which a firm can raise operating income by increasing sales; relates fixed cost to variable cost (ratio of fixed to variable costs).", "High operating leverage: high fixed, low variable cost; high BEP but large profit per incremental sale after BEP; losses grow faster below BEP.", "Low operating leverage: mostly variable cost; reaches BEP with small sales but earns small profit per extra sale.", "DOL = % change in operating income / % change in sales. DOL 2 means 25% rise in sales gives 50% rise in operating profit.", "Financial leverage is different: amount of debt in capital structure (equity and liabilities side of balance sheet)."]}, {"heading": "Cost indifference point (gold jewellery example)", "points": ["Option 1 (automation): F = 1,00,00,000/yr, V = 4,000, S = 5,000, contribution 1,000.", "Option 2 (labour intensive): F = 10,00,000/yr, V = 4,600, S = 5,100, contribution 500.", "Indifference: 1,000Q - 1,00,00,000 = 500Q - 10,00,000, so 500Q = 90,00,000 and Q = 18,000 units.", "Sales well above 18,000: choose automation; well below: labour-intensive; near 18,000: both similar."]}, {"heading": "Assumptions, limitations, inventory cost", "points": ["Limitations: fixed cost may vary with turnover and time; variable cost may fall with economies of scale; not all output is sold (inventory changes).", "Assumes any desired quantity can be sold; no inventory build-up is hard in reality; multiproduct case assumes constant product mix; hard for many products.", "Only analyses scenarios; data are futuristic. Still, advantages outweigh limitations, and errors neutralise when comparing several businesses.", "Inventory costs money: Rs 10 million working capital loan at 15% costs Rs 1.5 million interest; cutting loan to Rs 5 million cuts interest to Rs 0.75 million. Unborrowed inventory still has opportunity cost."]}], "cases": [{"name": "Readymade shirt business", "crux": "F = 6,35,000, V = 575, S = 800; contribution 225, BEP 2,823 shirts, margin of safety 2,177 at 5,000 planned units."}, {"name": "Semi-variable R&M example", "crux": "F 30,000, V 20, S 30: BEP 3,000 units; 2,000 units loses Rs 10,000; 4,000 units needed for Rs 10,000 profit."}, {"name": "Six-year projection table", "crux": "Fixed 955 per year against contribution of 10% of sales; loss shrinks yearly and break-even comes in year 6 with profit 45."}, {"name": "10 carat gold jewellery: automation vs labour", "crux": "Cost indifference at 18,000 units; high-fixed automation wins only if expected sales are well above that."}, {"name": "Inventory financing", "crux": "Efficient inventory management halving bank borrowing cuts interest from 1.5 to 0.75 million and can turn loss into profit."}, {"name": "Supply-demand price discovery", "crux": "Demand up raises price and quantity; supply up lowers price and raises quantity; both shifts together move equilibrium accordingly."}], "keyTerms": [{"term": "Fixed cost", "def": "Expense that does not change with activity level within the period; incurred even at zero output."}, {"term": "Variable cost", "def": "Cost proportional to level of activity; constant per unit."}, {"term": "Semi-variable cost", "def": "Cost with fixed and variable parts, e.g. insurance (treat fixed) and maintenance (treat variable)."}, {"term": "Cost driver", "def": "Factor whose change causes change in the cost of an activity."}, {"term": "Contribution margin", "def": "Selling price per unit minus variable cost per unit; used to recover fixed cost then generate profit."}, {"term": "Break-even point", "def": "Production and sales level where total revenue equals total cost; no profit no loss."}, {"term": "Margin of safety", "def": "Amount by which planned sales exceed break-even sales; cushion before loss."}, {"term": "Operating leverage", "def": "Extent of fixed relative to variable cost; determines how strongly operating income responds to sales."}, {"term": "Degree of operating leverage (DOL)", "def": "Percentage change in operating income divided by percentage change in sales."}, {"term": "Financial leverage", "def": "Amount of debt in the capital structure."}, {"term": "Cost indifference point", "def": "Volume at which two alternative cost structures give equal profit."}], "formulas": [{"name": "Profit", "expr": "P = Q*S - (Q*V + F)", "note": "Base equation for every CVP problem."}, {"name": "Unit contribution", "expr": "CM = S - V", "note": "Per-unit amount available to recover fixed cost."}, {"name": "Total contribution", "expr": "Total sales - Total variable cost", "note": "Profit = total contribution - F."}, {"name": "Break-even quantity", "expr": "Q_BEP = F / (S - V)", "note": "Round up to next whole unit (e.g. 2,822.2 becomes 2,823)."}, {"name": "Target profit quantity", "expr": "Q = (F + Target profit) / (S - V)", "note": "Equivalently BEP + target profit / CM."}, {"name": "Margin of safety", "expr": "MoS = Planned sales - BEP sales", "note": "In units or rupees; negative means operating below BEP."}, {"name": "Degree of operating leverage", "expr": "DOL = % change in operating income / % change in sales", "note": "DOL 2 and sales +25% gives operating profit +50%."}, {"name": "Cost indifference point", "expr": "(S1 - V1)Q - F1 = (S2 - V2)Q - F2, so Q = (F1 - F2) / (CM1 - CM2)", "note": "Choose high-fixed option only if expected volume exceeds Q."}], "examAnswerTips": ["Always first build a table classifying every item as Fixed, Variable or Not a cost before computing anything.", "Exclude income tax and dividend entirely; they are not costs.", "Use the exam conventions: insurance fixed, maintenance variable, long-term loan interest fixed, short-term/working capital loan interest variable, salaries fixed, wages variable.", "Convert totals to per-unit variable cost (total variable cost / units) before computing contribution.", "State the formula, substitute values, and round BEP units upward.", "Show margin of safety and profit at the planned level, and comment on risk (high operating leverage = higher risk below BEP).", "Draw and label the break-even chart: fixed cost line, total cost line, sales line, BEP, loss zone, profit zone, margin of safety.", "Mention assumptions and limitations briefly at the end for full marks.", "Trap: the slide classification tables are inconsistent on insurance; follow the stated exam rule (insurance FIXED)."], "quiz": [{"q": "For examination purposes, how should insurance and maintenance be treated?", "options": ["Both fixed", "Both variable", "Insurance fixed, maintenance variable", "Insurance variable, maintenance fixed"], "answer": 2, "why": "Both are semi-variable; course rule: insurance fixed, maintenance variable."}, {"q": "Interest on a working capital (short-term) loan is classified as:", "options": ["Fixed cost", "Variable cost", "Not a cost", "Direct fixed cost"], "answer": 1, "why": "It varies with level of operation; long-term loan interest is fixed."}, {"q": "Which item is NOT a cost for BEP analysis?", "options": ["Depreciation", "Income tax", "Web-hosting", "Production bonus"], "answer": 1, "why": "Income tax and dividend are not costs."}, {"q": "F = Rs 6,35,000, S = Rs 800, V = Rs 575. BEP in units is:", "options": ["2,500", "2,823", "3,823", "1,104"], "answer": 1, "why": "6,35,000 / 225 = 2,822.2, rounded up to 2,823."}, {"q": "F = 30,000, V = 20, S = 30. Units needed for a profit of Rs 10,000?", "options": ["3,000", "3,500", "4,000", "5,000"], "answer": 2, "why": "(30,000 + 10,000) / 10 = 4,000."}, {"q": "Same data (F 30,000, V 20, S 30), production 2,000 units. Result?", "options": ["Profit 10,000", "Loss 10,000", "Break-even", "Loss 20,000"], "answer": 1, "why": "Revenue 60,000 minus cost 70,000 = loss 10,000."}, {"q": "Sales 40,000 for 500 units, total variable cost 15,000, fixed cost 20,000. BEP units?", "options": ["250", "400", "500", "600"], "answer": 1, "why": "S 80, V 30, CM 50; 20,000 / 50 = 400."}, {"q": "In the same exercise, profit at 600 units is:", "options": ["Rs 5,000", "Rs 10,000", "Rs 30,000", "Rs 20,000"], "answer": 1, "why": "600 x 50 - 20,000 = 10,000."}, {"q": "Automation: F 1 crore, CM 1,000. Labour model: F 10 lakh, CM 500. Cost indifference quantity?", "options": ["9,000", "18,000", "20,000", "1,80,000"], "answer": 1, "why": "(1,00,00,000 - 10,00,000) / (1,000 - 500) = 18,000."}, {"q": "A firm has DOL of 2. If sales rise 25%, operating profit rises by:", "options": ["12.5%", "25%", "50%", "100%"], "answer": 2, "why": "DOL x % change in sales = 2 x 25%."}, {"q": "High operating leverage implies:", "options": ["Low BEP and small profit per extra unit", "High BEP and large profit per extra unit after BEP", "High debt in capital structure", "Variable costs dominate"], "answer": 1, "why": "High fixed relative to variable cost raises BEP but increases contribution per unit beyond it."}, {"q": "Planned sales 5,000 units, BEP 2,823 units. Margin of safety?", "options": ["2,823", "2,177", "1,000", "7,823"], "answer": 1, "why": "5,000 - 2,823 = 2,177 units."}], "slug": "L09_Break_Even", "excluded": "Syllabus up to slide 76 ('syllabus for this topic is up to this slide'); slide 71 marked 'neglect for exam'."}, {"id": "L10", "title": "Marketing Research", "oneLiner": "What marketing research is, why a startup needs it from the idea stage onward, its types (by source, methodology, objective), the five primary methods and the step-by-step research process.", "examRelevance": "Classic long question: lay out the step-by-step market research process for a given startup (e.g. organic food restaurant) with the rationale for each step and the type of data used at each stage (secondary vs primary, qualitative vs quantitative, exploratory vs descriptive vs causal). Short questions may ask to match a primary method (survey, focus group, interview, observation, experiment) to a situation.", "sections": [{"heading": "Definition and why it matters", "points": ["Marketing research = systematic and objective process to design methodology, collect market data, analyze it into information, disseminate it to decision makers, and use it to improve decisions.", "Goal: create customer value and satisfaction, gain market access, achieve profitable growth.", "Supports decisions on opportunities, target market selection, segmentation, marketing programs, performance and control.", "58% of founders polled said they would have done more market research before launch (same % wished for a stronger business plan).", "Quote stressed: 'It is a capital mistake to theorise before one has data' (Conan Doyle)."]}, {"heading": "Research is continuous, from idea stage", "points": ["Starts at the idea stage, ideally while identifying the pain point, and continues as long as the company exists.", "Decides whether to keep developing, which features to focus on, add or discard.", "Customers are part of product development; research averts building the wrong product and reduces launch rejection.", "Lean method: continue development on validated learning; engage customers to validate, learn and decide.", "Market attractiveness: market size, historical, present and future growth, and market type (perfect competition, monopolistic competition, oligopoly, monopoly)."]}, {"heading": "Activities research supports (by funnel stage)", "points": ["Awareness: awareness/attitudes/usage research, PR research, advertising research.", "Targeting: market segmentation, positioning and branding research, industry and competition analysis.", "Acquisition: concept testing, product optimization, pricing research, advertising and usability testing.", "Retention: customer satisfaction and loyalty, communication testing, usability, customer experience and shopper insights.", "Each can be qualitative and quantitative."]}, {"heading": "SWOT analysis", "points": ["Strengths: where the company excels over competitors.", "Weaknesses: areas where it is weak and must improve.", "Opportunities: favourable factors it can exploit to build competitive advantage.", "Threats: factors that can harm performance or weaken competitive advantage."]}, {"heading": "Three ways to classify market research", "points": ["By source of data: primary vs secondary.", "By methodology / type of data: qualitative vs quantitative.", "By objective: exploratory, descriptive, causal."]}, {"heading": "Primary vs secondary sources", "points": ["Primary: collected directly and specifically for the problem at hand; cost, time and resources high, sometimes prohibitive.", "Secondary: collected routinely for general use or another problem, reused now; cheaper and faster, often published (third-party data).", "Typical sequence: start with low-cost secondary/exploratory data, then collect primary data for more confidence."]}, {"heading": "Qualitative vs quantitative", "points": ["Quantitative: answers what, where, when, who; quantifies and generalizes; large sample, statistical; surveys (online, phone, paper), POS transactions, click-streams; more objective.", "Qualitative: answers why and how; insight into deeper motives and trends; observation, unstructured questioning, focus groups, triads, dyads, in-depth interviews, ethnography; exploratory, less objective."]}, {"heading": "By objective: exploratory, descriptive, causal", "points": ["Exploratory: preliminary data to develop an idea, outline concepts, gather insights, formulate hypotheses; low cost (focus groups, interviews, observation).", "Descriptive: precisely describe an element, e.g. who the target market is, how large, how it will develop; high cost (questionnaire survey).", "Causal/experimental: test cause and effect, e.g. 'if x increases what happens to y', price elasticity, ad spend vs sales; done through experiments/field trials.", "Exploratory and descriptive can each be qualitative or quantitative."]}, {"heading": "Five primary data methods", "points": ["Survey: most widely used; objective, specific metric, large sample, needs resources; mostly quantitative (e.g. new product launch).", "Focus group: homogeneous demographic (college gamers, newly wed women, new moms) with a moderator; exploratory, qualitative (e.g. new product testing).", "Individual interview: qualitative deep exploration of problems, psychological motivations, perceptions.", "Observation: usability test, eye tracking, contextual inquiry, in-home observation, mystery shopper (e.g. food); mostly qualitative.", "Experiment and field trial: scientific test of a hypothesis (features, price, packaging, aesthetics); quantitative; e.g. A/B test by Obama team."]}, {"heading": "Research process (step by step)", "points": ["1. Define the problem/objective and design the research methodology (choose exploratory/descriptive/causal; source; method).", "2-3. Collect data: secondary first (cheap, fast), then primary via survey, focus group, interview, observation or experiment.", "4. Analyse: statistical manipulation (e.g. regression) for quantitative data or subjective analysis of focus groups for qualitative; analysis type differs by data type.", "5. Present/apply findings: overall conclusions, not overwhelming statistics; oral presentation, written conclusions with analysis, data tables; use for decisions.", "Questionnaire wording matters: question framing changes answers (smoking whilst praying vs praying whilst smoking)."]}], "cases": [{"name": "Organic food restaurant (exercise)", "crux": "Start with exploratory research on secondary data (low cost); for confidence collect primary data: focus groups, interviews, observation (exploratory) then questionnaire survey or field trial (descriptive/causal), budget permitting."}, {"name": "HarperCollins / Agatha Christie (1985)", "crux": "Declining sales; quantitative and qualitative research showed readers liked the 'niceness' of crimes but covers were gruesome. New covers raised first-year sales by 40%."}, {"name": "Obama campaign A/B test (Optimizely)", "crux": "Experiment on donation page showed images did better than video. Lessons: every visitor is an opportunity, question your assumptions, experiment early and often."}, {"name": "Smoking and praying question", "crux": "'Approve of smoking whilst praying?' gets No; 'praying whilst smoking?' gets Yes. Wording of survey questions biases answers."}], "keyTerms": [{"term": "Marketing research", "def": "Systematic, objective process of designing research, collecting and analysing market data and disseminating information for better decisions."}, {"term": "Primary data", "def": "Collected directly for the current problem; costly and slow but specific."}, {"term": "Secondary data", "def": "Collected earlier for general use or another problem; cheaper, faster, often published."}, {"term": "Qualitative research", "def": "Answers why and how; small samples, focus groups, interviews, observation; exploratory, less objective."}, {"term": "Quantitative research", "def": "Answers what, where, when, who; large samples, surveys, statistics; generalizable, more objective."}, {"term": "Exploratory research", "def": "Preliminary research to gather insights and formulate hypotheses."}, {"term": "Descriptive research", "def": "Precisely describes the market: who, how large, how it will develop."}, {"term": "Causal research", "def": "Experiments testing cause and effect, e.g. price elasticity."}, {"term": "A/B test", "def": "Field experiment comparing two variants to see which converts better."}, {"term": "Focus group", "def": "Moderated discussion with a homogeneous demographic group; qualitative, exploratory."}, {"term": "SWOT", "def": "Strengths, Weaknesses, Opportunities, Threats analysis."}], "examAnswerTips": ["Structure the process as numbered steps: define problem, design research, collect secondary data, collect primary data, analyse, present and apply; give a one-line rationale for each.", "At every step label the data: primary or secondary, qualitative or quantitative, and exploratory, descriptive or causal.", "Justify order by cost: secondary and exploratory first (cheap), primary and descriptive/causal later when confidence and budget are needed.", "Apply to the startup in the question with concrete methods (e.g. focus group of health-conscious diners, survey of 500 locals, A/B test of menu prices).", "Mention research is continuous and lean: validate with customers before and after launch.", "Quote a supporting case (Agatha Christie covers, Obama A/B test) to show impact."], "quiz": [{"q": "Which type of research answers the 'why' and 'how' of consumer behaviour?", "options": ["Quantitative", "Qualitative", "Causal", "Descriptive"], "answer": 1, "why": "Qualitative research seeks deeper motives behind purchases."}, {"q": "Testing how a 10% price cut affects sales is an example of:", "options": ["Exploratory research", "Descriptive research", "Causal research", "Secondary research"], "answer": 2, "why": "Causal research tests cause and effect, e.g. price elasticity, through experiments."}, {"q": "Which primary method is described as the most widely utilized?", "options": ["Survey", "Focus group", "Observation", "Interview"], "answer": 0, "why": "Survey: objective, specific metric, large sample."}, {"q": "Mystery shopper and eye tracking belong to which primary method?", "options": ["Experiment", "Interview", "Observation", "Survey"], "answer": 2, "why": "Listed under observation along with usability tests and contextual inquiry."}, {"q": "Why should a startup begin with secondary data?", "options": ["It is always more accurate", "It is cheaper and faster than primary data", "Investors require it", "It is quantitative only"], "answer": 1, "why": "Primary data is costly and slow; secondary is cheaper and faster for exploratory work."}, {"q": "What did HarperCollins change after research on Agatha Christie novels?", "options": ["Price", "Book covers", "Distribution", "Story content"], "answer": 1, "why": "Covers were gruesome; new covers raised sales 40% in the first year."}, {"q": "Per the slides, what share of founders wished they had done more market research before launching?", "options": ["28%", "42%", "58%", "75%"], "answer": 2, "why": "58% said so."}, {"q": "Focus groups are best suited for:", "options": ["Causal, quantitative research", "Exploratory, qualitative research", "Large-sample descriptive research", "Secondary research"], "answer": 1, "why": "Homogeneous group with a moderator, excellent for exploratory and qualitative research."}, {"q": "The Obama campaign A/B test taught that:", "options": ["Video always beats images", "Images did better than video, so question assumptions", "Experiments should be done only after launch", "Surveys beat experiments"], "answer": 1, "why": "Lessons: question assumptions, experiment early and often."}], "slug": "L10_Market_Research", "excluded": "Crossed-out slide 32 excluded."}, {"id": "L11", "title": "Business Plan", "oneLiner": "What a business plan is, its purposes, the startup journey it fits into, and the chapter-by-chapter contents (Vaughan Evans structure, Sequoia and Forbes templates) of a winning plan.", "examRelevance": "The project report / business plan is the announced 30-mark question: write a structured plan with executive summary, business, market demand, competition, strategy, resources, financials (P&L, cash flow, balance sheet, fund requirement and sources), risks and sensitivities, rewards and conclusion.", "sections": [{"heading": "Definition and business model vs plan", "points": ["Business plan: strategic blueprint outlining your vision and systematically detailing key components and strategies for success; a roadmap of goals and how to achieve them.", "Ideally explains why you will succeed, leveraging strengths and opportunities given the challenges ahead.", "Business model: the business taken up to solve a customer segment's problem through superior value proposition, delivered competitively to create wealth (e.g. e-bike maker).", "Business plan is a description of the business model: execution plan, SWOT, USP, team, business process management, competitive strategies, customer acquisition and retention, financial performance, value for investors."]}, {"heading": "Where the plan fits: startup journey and phase-wise funding", "points": ["Problem identification phase: identify a pain, empathize, set vision, generate ideas, assess value proposition, elementary market research, inputs availability, demand-supply, feasibility.", "Then build MVP, validate with early adopters, market discovery, examine revenue model and cost structure, prepare detailed business plan for pitching.", "Register company only when absolutely necessary (when approaching investors). Delay fundraising: bootstrap, friends and relatives, angels after validation.", "Government support named: DSIR-PRISM, TIFAC-SRIJAN seed money, SIDBI Venture Capital equity, MSME schemes. Follow Build-Measure-Learn (Lean Startup).", "Myth: once you have an idea, the first thing to do is prepare the business plan.", "Identify pain / motivation: bootstrap, own funds. Build MVP: bootstrap, friends, relatives; find cofounders.", "Business plan, incubation, acceleration: angel investors; hire early employees, register company, market discovery.", "Go-to-market: angels or early-stage VC. Business process management: VC. Growth: VC rounds; hire a professional CEO."]}, {"heading": "Purposes of a business plan (flavour varies)", "points": ["Entrepreneur's ready reckoner: dynamic, strategy and milestone oriented; also for mentor connection.", "Equity fund raising (angel/VC): success and risk factors with mitigation, traction, product development and validation, financial projection, exit strategy.", "Debt fund raising: present and future financials. Business plan competitions: as equity plus social values. Incubation and acceleration: as equity.", "Customer connection: past and present financials. Acquirer in M&A: present and future financials, customer base.", "Whatever the motive, tell the story of how you navigate challenges to emerge successful and create value."]}, {"heading": "Essence of a good plan", "points": ["Investors are busy: convey maximum in minimum words, no poetic phrases; give an MVP of the plan (lean).", "Tell a good story with strong words; gather information on pitfalls; highlight risks as much as prospects; show investors the money.", "Demonstrate a working prototype or MVP even if shabby; it validates claims of novelty.", "Steve Blank: 99.7% of funding applications are rejected (0.3% accepted), so plans must grab attention fast."]}, {"heading": "Four critical factors (pride of place)", "points": ["People: founders, employees, mentors, directors; team chemistry, track record, complementary skills.", "Opportunity: what you sell, to whom, the pain alleviated, how you make money, unique value proposition, market size, growth, competition.", "Context: big picture, current scenario, growth prospect, market structure; timing (Bill Gross; Victor Hugo on an idea whose time has come).", "Risk and reward: what can go wrong and potential gain if done right."]}, {"heading": "USP and value proposition", "points": ["USP: combination of factors that set your product apart and tell customers why to buy (delivery, return policy, aftersales). Should be in company DNA.", "Effectiveness depends on resonance with target audience and their pain points.", "USP types: innovative technology, cost-effective, customer-centric, sustainability, agility, unique design/branding, personalization, social impact, ease of use, speed.", "Examples: FedEx overnight, Avis we try harder, M&Ms melts in mouth, Domino's 30 minutes or free, Geico 15 minutes could save 15%, Bee's Wrap, Enterprise."]}, {"heading": "Templates", "points": ["Sequoia (15-20 slides): company purpose, problem, solution, why now, market size, competition, product, business model, team, financials.", "Forbes / Dave Lavinsky: I executive summary, II company overview, III industry analysis, IV customer analysis, V competitive analysis, VI marketing plan, VII operations plan, VIII management team, IX financial plan, X appendix.", "Forbes financial plan covers revenue model, financial highlights, funding requirements, use of funds, exit strategies. Management covers members, gaps, board.", "Business model canvas blocks: key partners, key activities, key resources, value proposition, customer relationship, channel, customer segment, cost structure, revenue model."]}, {"heading": "Vaughan Evans chapters 1-2", "points": ["Chapters: 1 executive summary, 2 the business, 3 market demand, 4 competition, 5 strategy, 6 resources, 7 financial outlay, closure and projections, 8 risks, opportunities, rewards, sensitivities; then conclusion.", "Executive summary: the business, team, proposal, why now, why it will succeed, rewards to investors, major risks and mitigation. Often the only part read; hone and edit it remorselessly.", "First impression forms in about 15 seconds; be persuasive, brief but complete, keep readers expecting more.", "The business, background: opener, goals and objectives, strategy, resources, basic financials; then business mix by segment (customer persona, benefits, product-market fit, evidence)."]}, {"heading": "Opener, goals, resources, basic financials", "points": ["Opener (one paragraph): who you are, products/services, main customer groups, where based and selling, success in revenue and operating margin, by which year.", "Goals are directional, objectives specific and SMART (Specific, Measurable, Attainable, Relevant, Time-limited), e.g. 10% market share by end 2026.", "Resources: location, infrastructure, strategic assets, technology, IP, team skills, mentors, suppliers, distribution; list needs vs availability of personnel, technology, finances, distribution, promotion, products, services.", "Basic financials: key metrics like sales and operating profit; if no sales, major expenses, their source and time."]}, {"heading": "Chapters 3-6: market, competition, strategy, resources", "points": ["Market demand: market size, growth, test marketing, addressable and obtainable market; use real data, do not suppress facts; who buys, how much, at what price, why, future.", "Competition: respect competitors (dismiss them and readers dismiss you); USP, Porter's five forces, value proposition.", "Strategy: competitive position on entry and over three years; be realistic. Sustain advantage via patents, sustained innovation, process improvement, content marketing, branding, customer relationships.", "Resources: technology, personnel (management, marketing, operations), inputs, logistics, finance. Investors back visionary leaders, not managers."]}, {"heading": "Chapters 7-8 and conclusion", "points": ["Financials: total fund requirement, customers/users, revenue, gross, operating and net profit for years I-III.", "Present forecast P&L (sales from market research), forecast cash flow (liquidity), forecast balance sheet (achievable with acceptable debt-equity structure); details in appendix; mind assumptions.", "Risks: likelihood, mitigation, worst and best case. Opportunities hidden in adversity. Rewards: pay-off estimates for investors and founders.", "Sensitivities: numerical effect on cash flow if big risks manifest (e.g. price down 5%, input cost, interest, customer acquisition cost).", "Conclusion: why worthy of backing across demand, competition, strategy, resources, financials, risk; address audience, end with value to investors and society (e.g. 10X in three years)."]}, {"heading": "Length and style", "points": ["Main document 25-30 A4 pages, maximum 35. Market demand, competition, strategy 3-4 pages each; resources and financials 4-6 pages each.", "Chapters 2 and 8 about two pages each; conclusion an upbeat half page.", "Use words sparingly, simple sentences, headings, subheads, lists, graphics judiciously so it can be skimmed in 15 seconds.", "Write it yourselves with key team members; investors care about cashing out; never disparage competition; know your own weaknesses."]}], "cases": [{"name": "Hike Messenger (Kavin Mittal)", "crux": "Unicorn at $1.4 B valuation and $261M+ raised, but scaled from 150 to 400 people too fast with top-level hiring mistakes and failed to adapt; shut down and pivoted to Rush Gaming."}, {"name": "Dharmesh Shah, HubSpot", "crux": "Startup plans go stale before the ink dries; few startups resemble their original plan, so keep plans dynamic."}, {"name": "Jeff Bezos 70% rule", "crux": "Decide with about 70% of the information you wish you had; being slow is costlier than course-correcting."}, {"name": "Pareto 80:20", "crux": "Roughly 80% of effects come from 20% of causes, e.g. 80% of sales from 20% of customers."}, {"name": "Elon Musk and Tesla", "crux": "Persist if you believe in the idea; Tesla nearly went bankrupt but got funds on the day; but do not beat a dead horse."}, {"name": "Steve Blank statistic", "crux": "99.7% of funding applications are rejected, so precision and attention-grabbing matter."}, {"name": "IIT Kharagpur ecosystem", "crux": "Promotes entrepreneurship through curriculum, mentoring, hackathons, incubation (infrastructure, seed funds, IP filing) and acceleration."}], "keyTerms": [{"term": "Business plan", "def": "Strategic blueprint and roadmap describing goals, strategies and execution of a business model."}, {"term": "Business model", "def": "How a business solves a customer segment's problem with superior value proposition and delivers it competitively to create wealth."}, {"term": "Executive summary", "def": "Opening chapter covering business, team, proposal, why now, why it will succeed, rewards and risks."}, {"term": "USP", "def": "Unique selling proposition: differentiators that tell customers why to buy yours."}, {"term": "SMART objectives", "def": "Specific, Measurable, Attainable, Relevant, Time-limited."}, {"term": "Sensitivities", "def": "Numerical estimate of how cash flow changes if key risks manifest."}, {"term": "MVP", "def": "Minimum viable product used for validated learning with early customers."}, {"term": "Financial closure", "def": "Point at which the full project outlay is tied up from identified sources."}, {"term": "Addressable and obtainable market", "def": "Total market you could serve and the share you can realistically capture."}], "formulas": [{"name": "Operating margin (for the opener)", "expr": "Operating profit / Sales", "note": "Quote alongside revenue in the opener paragraph."}], "examAnswerTips": ["For the 30-mark project report, use clear headings following Vaughan Evans: Executive summary, The business, Market demand, Competition, Strategy, Resources, Financials, Risks/opportunities/sensitivities, Rewards, Conclusion.", "Include numbers: market size, target share (SMART), fund requirement split into fixed capital and working capital, sources of funds (equity, debt, grant), 3-year projected revenue and profits, BEP.", "Present projected P&L, cash flow and balance sheet in table form; state assumptions.", "Cover the four critical factors: people, opportunity, context, risk and reward.", "Show USP and value proposition explicitly and do not disparage competitors; use Porter's five forces.", "Add a sensitivity line (e.g. price down 5%) and investor exit/returns; end with value to investors and society.", "Distinguish business plan from business model if asked."], "quiz": [{"q": "Which is the first chapter in Vaughan Evans' business plan structure?", "options": ["Market demand", "Executive summary", "Competition", "Resources"], "answer": 1, "why": "Chapter 1 is the executive summary."}, {"q": "The recommended main document length is:", "options": ["5-10 pages", "10-15 pages", "25-30 pages, max 35", "100+ pages"], "answer": 2, "why": "Slides: 25-30 A4 pages, maximum 35."}, {"q": "Which is NOT one of the four critical factors?", "options": ["People", "Opportunity", "Context", "Dividend policy"], "answer": 3, "why": "Four factors: people, opportunity, context, risk and reward."}, {"q": "SMART objectives stand for Specific, Measurable, Attainable, Relevant and:", "options": ["Tactical", "Time-limited", "Targeted", "Tangible"], "answer": 1, "why": "T is time-limited."}, {"q": "A plan for debt fund raising should mainly focus on:", "options": ["Exit strategy", "Present and future financials", "Social values", "Past financials only"], "answer": 1, "why": "Slides: debt raising focuses on present and future financials."}, {"q": "Sensitivities in a business plan mean:", "options": ["Emotional appeal", "Numerical impact on cash flow if key risks occur", "Customer complaints", "Legal risks only"], "answer": 1, "why": "E.g. effect of 5% price fall on cash flow."}, {"q": "Per Steve Blank, roughly what share of funding applications are accepted?", "options": ["30%", "3%", "0.3%", "10%"], "answer": 2, "why": "99.7% rejected, 0.3% accepted."}, {"q": "Which item is in the Sequoia template?", "options": ["Why now", "Dividend history", "Tax returns", "Audit report"], "answer": 0, "why": "Sequoia: purpose, problem, solution, why now, market, competition, product, model, team, financials."}, {"q": "The forecast balance sheet in a plan mainly shows:", "options": ["Liquidity", "Forecasts achievable with acceptable debt-equity structure", "Customer satisfaction", "USP"], "answer": 1, "why": "Cash flow shows liquidity; balance sheet shows capital structure."}, {"q": "Hike Messenger's downfall was attributed mainly to:", "options": ["No funding", "Hiring too fast with top-level hiring mistakes and not adapting", "Government ban", "Patent loss"], "answer": 1, "why": "Grew 150 to 400 people quickly; bad hires at the top."}, {"q": "When should a startup register the company, per the slides?", "options": ["Before ideation", "Only when absolutely necessary, e.g. approaching investors", "Never", "After IPO"], "answer": 1, "why": "Register when approaching investors."}], "slug": "L11_Business_Plan", "excluded": "Crossed-out slides 28–32, 64–65, 69–70, 80–92 excluded."}, {"id": "L12", "title": "Pitching", "oneLiner": "How to pitch a startup: elevator pitch formats (1-liner, 30 s, 2-3 min), Guy Kawasaki's 10/20/30 rule and ten slides, the Airbnb deck, storytelling, delivery dos and don'ts, and when to fundraise.", "examRelevance": "Likely asked to write a 30-second elevator pitch for a given startup (what, for whom, how different, plus traction and ask), list the 10 Kawasaki slides, or advise a founder afraid of idea theft when pitching. Short MCQs on the 10/20/30 rule, pitch lengths and story elements.", "sections": [{"heading": "Entrepreneurship vs business management education", "points": ["Entrepreneurship: creation and innovation; launch new venture under extreme uncertainty; opportunity recognition; calculated risk-taking, fail fast.", "Management: optimization and operation of existing organizations; efficiency and stability; risk avoider/controller.", "Entrepreneurship tools: MVP, customer discovery, burn rate, growth KPIs. Management tools: balance sheets, income statements, budgets, ROI, quality metrics.", "Entrepreneurship learning is experiential, project-based (incubators, design thinking, lean startup); management uses case studies and structured assignments.", "Careers: founders, innovation consultants, VC analysts, social entrepreneurs vs corporate managers, operations heads, marketing/HR/finance executives."]}, {"heading": "Key pitching principles", "points": ["Investors: 'We don't invest on a dot but a line' - show progress over time.", "Don't pitch without building: have an MVP.", "Avoid too much information, too little communication; make it understandable to your grandmother.", "No one-size-fits-all: separate decks for investors and customers.", "Three formats: 1-liner, 30 seconds, and 3-20 minutes; be ready for one sentence, one minute, ten minutes."]}, {"heading": "Pitch formats", "points": ["1-liner: what we do, for whom, and how we do it differently.", "30 seconds: 1-liner plus traction (repeat customers, angel funding, testimonials, referrals).", "30-second content: pain point, solution/USP, market and reward (TAM/SAM/SOM), traction and financials; show you are moving fast.", "2 minutes: unique insight (aha, competitive advantage), how you make money, team credentials, how much money you ask and its use.", "3 minutes: 10 slides plus storytelling (the why of your business).", "Keep a ~2-minute video pitch on a privately sharable YouTube channel for telephonic introductions."]}, {"heading": "Elevator pitch", "points": ["Precise description of your company in the fewest words giving a holistic view of strengths, for people who matter but don't know you.", "No longer than 60 seconds, ideally 20-30 seconds; helps audience decide if your proposition interests them.", "Convey what makes you unique and why you will succeed.", "Nutshell: who you are and vision; what you do; why winning proposition (USP); leave something for future reference; seek an appointment; practice."]}, {"heading": "Guy Kawasaki 10/20/30 rule and ten slides", "points": ["10 slides, no more than 20 minutes, no font smaller than 30 points.", "1 Title, 2 Problem/Opportunity, 3 Value proposition, 4 Underlying magic (technology, secret sauce), 5 Business model (revenue model).", "6 Go-to-market plan, 7 Competitive analysis, 8 Management team, 9 Financial projection (3-year revenue, profit, customers), 10 Traction, timeline, use of funds.", "Show product demo/prototype after slide 4.", "Less text, more diagrams, schematics, flowcharts; 'a prototype is worth 10,000 slides' (Glen Sires, Google).", "Prof's tip: first slide as an abstract/infographic, ideally the elevator pitch, or a short captivating origin story.", "Also cover reward to investors and desired fundraising; content matters more than template; have compelling reasons, not just enough reasons."]}, {"heading": "Business plan essence for investors", "points": ["Investors are busy: convey maximum in fewest words, no poetic phrases.", "Lean philosophy: give an MVP of the plan.", "Tell a good story with strong words.", "Gather information on pitfalls; highlight risks as much as prospects.", "Show investors the money."]}, {"heading": "Delivery dos and don'ts", "points": ["Don't be verbose, use rare jargon, speak too fast or ramble; vary voice pitch.", "Leave a catchy flyer, visiting card or innovative takeaway (e.g. calendar).", "Practice and refine; plan, rehearse and perform before a live audience; 1 hour preparation per minute of presentation (Wayne Burgraff).", "Stay open to interjection; remain absolutely polite, keep ego at bay.", "Good attire, relaxed, move (avoid the podium), no self-praise or bashing competitors.", "Body language: movements mirror words, hold gaze a few seconds per person, listen fully, mirror body language, mild smile, no fidgeting.", "'PowerPoint is not the message nor the messenger' (David Fernandez) - you are the messenger.", "Success judged by what the listener receives (Lily Walters)."]}, {"heading": "Storytelling", "points": ["Story attracts passionate employees, lets investors gauge conviction and tenacity, connects customers to your narrative.", "About 70% of millennials prefer brands supporting a social cause they care about.", "A compelling story can be more persuasive than growth projections - do both.", "Five building blocks (Maxwell and Dickman): Hero (agent of change), Antagonist (force you push against), Awareness (turning point, solution found), Transformation (results of hero's effort), Passion (driving force)."]}, {"heading": "When to fundraise", "points": ["Gain as much traction as possible first, so investors ask you to take their money.", "Empirically 90% of startups can take their product to market with very little money.", "Ask for enough to reach the next milestone, even if small.", "Don't show desperation; do homework on how much and how you will use it."]}], "cases": [{"name": "Hypothetical after-sales support startup (elevator pitch)", "crux": "Manages after-sales engagement for consumer durable brands at 2% of sales, cost 50% of billing; 2 MNC clients in Mumbai with 25% sales growth; market $100B, SAM $20B; $1M funding for $2M profit and 10X return."}, {"name": "Airbnb (AirBed&Breakfast) pitch deck", "crux": "Winning deck: cover, problem, solution, validation, market size, product, business model, adoption, competition, advantages, team, press, testimonials, financials. Company exceeded $100B market cap (2021)."}, {"name": "Airbnb problem and market", "crux": "Price matters in online travel booking, hotels disconnect you from local culture, no easy way to book with a local. Validation: craigslist 670,000 users, Couchsurfing 17,000 listings; TAM 2B+ trips, SAM 560M, SOM 84M (15% of SAM)."}, {"name": "Airbnb business model and ask", "crux": "10% commission; 84M trips x $25 average fee (at $80/night for 3 nights) = $200M projected revenue. Ask: $500K angel round for 12 months to reach 80K transactions and $2M revenue."}, {"name": "Airbnb competitive advantage", "crux": "First to market for transaction-based temporary housing, ease of use (book in 3 clicks), host profiles, list once (vs daily on craigslist), memorable design and brand, host incentive to earn money."}, {"name": "Blake Mycoskie / TOMS", "crux": "Saw barefoot children in villages while travelling, created TOMS footwear for them; stakeholders rallied around the cause making TOMS a household name. Illustrates hero, antagonist (pain of being barefoot), passion."}, {"name": "Guy Kawasaki", "crux": "Chief evangelist of Canva, formerly of Apple; author of The Art of the Start; proposed the 10/20/30 rule."}], "keyTerms": [{"term": "Elevator pitch", "def": "Short prepared speech, ideally 20-30 s and under 60 s, conveying what you do, for whom, your uniqueness and why you will succeed."}, {"term": "1-liner", "def": "What we do, for whom, and how differently."}, {"term": "Traction", "def": "Evidence of progress: repeat customers, funding, testimonials, referrals."}, {"term": "10/20/30 rule", "def": "10 slides, 20 minutes max, minimum 30-point font (Guy Kawasaki)."}, {"term": "MVP", "def": "Minimum viable product; build one before pitching."}, {"term": "USP", "def": "Unique selling proposition, why your offer wins."}, {"term": "TAM / SAM / SOM", "def": "Total, serviceable and obtainable market sizes used in pitches."}, {"term": "Underlying magic", "def": "Kawasaki slide 4: technology or secret sauce behind the product."}, {"term": "Story building blocks", "def": "Hero, Antagonist, Awareness, Transformation, Passion."}], "examAnswerTips": ["For a 30-second pitch write about 70-90 words: one-liner (what, for whom, how different), pain, USP, market size (TAM/SAM/SOM), traction, revenue model, and the ask with expected return. Model it on the after-sales support example.", "Use concrete numbers (customers, growth %, market size, funding ask) - investors 'invest on a line, not a dot'.", "When listing Kawasaki's ten slides, number them in order and mention demo after slide 4 and the 10/20/30 rule.", "Idea-theft advice (not directly on slides; argue from them): investors back execution and traction, not ideas; build an MVP and show progress; pitch the what and why, not the secret sauce details; speed to market is your protection; rehearse a pitch that reveals value without revealing the underlying magic in depth.", "Add delivery tips briefly: practice, polite, no jargon, leave a takeaway, ask for a follow-up appointment.", "Use the story framework (hero, antagonist, awareness, transformation, passion) when asked about storytelling, with TOMS as the example."], "quiz": [{"q": "Guy Kawasaki's 10/20/30 rule means:", "options": ["10 minutes, 20 slides, 30 investors", "10 slides, 20 minutes, minimum 30-point font", "10 slides, 20 seconds, 30 words", "10 founders, 20% equity, 30 days"], "answer": 1, "why": "Ten slides, no more than twenty minutes, no font smaller than thirty points."}, {"q": "Ideal length of an elevator pitch per the slides:", "options": ["5-10 seconds", "20-30 seconds, under 60", "2-3 minutes", "10 minutes"], "answer": 1, "why": "No longer than 60 seconds, ideally 20 to 30 seconds."}, {"q": "A 30-second pitch is the 1-liner plus:", "options": ["Team bios", "Traction", "Full financials", "Product demo"], "answer": 1, "why": "Slide: 30 seconds = 1-liner plus tractions."}, {"q": "In Kawasaki's sequence, when should the product demo be shown?", "options": ["Before slide 1", "After slide 4", "After slide 9", "Never"], "answer": 1, "why": "Transition to prototype/demo after slide 4 (underlying magic)."}, {"q": "What does 'We don't invest on a dot but a line' mean?", "options": ["Investors want long decks", "Investors want to see progress over time", "Investors prefer linear businesses", "Investors want one big number"], "answer": 1, "why": "Investors want to see how the business is progressing."}, {"q": "In Maxwell and Dickman's story blocks, the 'antagonist' in the TOMS story is:", "options": ["Competitors", "Blake Mycoskie", "The pain of being barefoot", "Investors"], "answer": 2, "why": "Antagonist is the force the story pushes against: being barefoot."}, {"q": "Airbnb's business model was:", "options": ["Monthly subscription", "10% commission on each transaction", "Advertising revenue", "Freemium listings"], "answer": 1, "why": "Slide: we take a 10% commission on each transaction."}, {"q": "When is the best time to fundraise per the slides?", "options": ["Before building any product", "After gaining as much traction as possible", "Only at IPO", "When cash runs out"], "answer": 1, "why": "Gain traction so investors ask you to take their money; do not show desperation."}, {"q": "Which is NOT one of Kawasaki's ten slides?", "options": ["Underlying magic", "Go-to-market plan", "Press coverage", "Management team"], "answer": 2, "why": "Press appears in the Airbnb deck, not Kawasaki's ten."}], "slug": "L12_Pitching", "excluded": "Syllabus up to slide 47 (colour-theory slides beyond excluded); slide 40 crossed out."}, {"id": "L13", "title": "Competitive Advantage", "oneLiner": "Sources and drivers of competitive advantage - moats, entry barriers, pricing power, market types, differentiation, core competency - and Porter's Five Forces.", "examRelevance": "Expect: compare monopolistic, oligopolistic and perfect competition markets (table), explain product differentiation and its dimensions, list entry barriers/moats, pricing power, core competency, or apply Porter's Five Forces to a business.", "sections": [{"heading": "What competitive advantage is", "points": ["The skill necessary to outpace rivals.", "Derived from knowledge, technology, information/data, differentiators, and adapting offerings as markets evolve.", "Product-market fit that customers love, plus a brand narrative customers fall in love with.", "Unfair advantage: something that cannot be copied or bought; if you lack it, build and earn it over time."]}, {"heading": "It's an orchestra", "points": ["All functions - technology, operations, marketing, finance, HR, information - must perform at their best.", "Value proposition with product-market fit; customer is king - more loyal customers give pricing power and superior margins.", "Focus on a niche: understand target customers' unique needs, decision makers and psychology.", "Marketing and selling capability; narratives so resonant the product sells itself; delight customers at every touch point."]}, {"heading": "Drivers of competitive advantage", "points": ["Attractive market structure, great product, entry barrier, scalability, repeatability, easy product extension.", "Core competency, logistic advantage, great brand with loyal followers, pricing power, unique experience/meaning in product."]}, {"heading": "Entry barriers (moat)", "points": ["Competitive advantage as a protective moat that makes it hard for competitors to enter.", "Barriers: customer switching cost, technological edge, intangible assets, economies of scale, geographical barriers, access to strategic resources.", "Also: product differentiation, capital requirements, access to distribution channels, government policy, degree of firm concentration, brand loyalty, core competency.", "Most durable modern moats: network effects, data, repeat engagement within an ecosystem (Uber, Facebook, Starbucks, Amazon, Google 85% search share)."]}, {"heading": "Scalability, pricing power, repeatability", "points": ["Scalability: how easily the business grows; software is costly to build but cloned at tiny marginal cost (Amazon, Flipkart, Practo). Network businesses must scale to survive.", "Pricing power: ability to raise price without hurting demand (sole maker of a life-saving drug); comes from monopoly, brand loyalty, trust, superior VP; lets firms pass on input cost rises.", "Repeatability: customer acquisition cost is huge, so the model must make customers return so lifetime value yields profit."]}, {"heading": "Market types", "points": ["Monopolistic: ideally a single company, simple product, high entry barrier, high pricing power.", "Oligopolistic: small number of companies, differentiated products, high barrier, high pricing power - they usually collude.", "Perfect competition: many companies, homogeneous products, no entry barrier, no pricing power.", "Market structure factors: present and future growth, number of firms, share of largest firms, market size, nature of costs, integration, product differentiation, customer turnover."]}, {"heading": "Core competency, logistics, brand", "points": ["Core competency (Prahalad and Hamel): specialized expertise from harmonizing complex streams of technology and work activity; invisible, so cannot be copied; sustainably adds stakeholder value.", "Logistic advantage: nearness to inputs and markets, knowledge workers or cheap labour, efficient distribution network, existing ecosystem.", "Brand loyalty: storytelling builds emotional connection and belonging; loyal customers pay more, sustaining above-average profit."]}, {"heading": "Strategies and product differentiation", "points": ["Cost leadership (attractive price but avoid low-quality image); differentiation and positioning (Nike); operational effectiveness; adaptability; information advantage from data.", "Differentiation dimensions: quality, features, form, shape, style, packaging, size, price, variety, composition, availability.", "Also durability, reliability, maintainability, ease of installation and purchase, return policy, repurchase, exchange offer, loyalty program."]}, {"heading": "Porter's Five Forces", "points": ["Michael Porter (Harvard): five forces determine competitive intensity and market attractiveness.", "Horizontal: competitive rivalry (intense means price cuts), threat of new entrants (blocked by entry barriers, scale, first mover, brand loyalty), threat of substitutes (substitute quality, cost of change).", "Vertical: supplier power (many suppliers = you command terms; else sellers' market), buyer power (many buyers, switching cost, price sensitivity).", "Note: company and product lifespans are shrinking - don't rely on a past winning product; stay nimble and keep refining."]}], "cases": [{"name": "Bootstrapped Indian ventures", "crux": "Serum Institute (Adar Poonawalla, Rs 1,80,000 cr), Zoho (Sridhar Vembu, Rs 1,03,760 cr, 50+ products), Zerodha (Kamath brothers, Rs 87,760 cr), Bagmane Developers - large value built without external funding."}, {"name": "Uber, Facebook, Starbucks, Amazon, Google", "crux": "All have strong moats; Amazon US$670 bn revenue (2025), Google holds over 85% of search - durable moats from network effects, data and repeat engagement."}, {"name": "Amazon, Flipkart, Practo", "crux": "Examples of easily scalable e-commerce/network businesses."}, {"name": "Life-saving drug maker", "crux": "Sole manufacturer can raise price with little drop in volume - illustration of pricing power."}, {"name": "Nike", "crux": "Example of product differentiation and positioning strategy."}], "keyTerms": [{"term": "Competitive advantage", "def": "The skill/edge necessary to outpace rivals."}, {"term": "Unfair advantage", "def": "An advantage that cannot be copied or bought."}, {"term": "Moat / entry barrier", "def": "Protective advantage making it hard for competitors to enter."}, {"term": "Pricing power", "def": "Capacity to raise price without affecting customer demand."}, {"term": "Scalability", "def": "Ease with which a business can grow at low marginal cost."}, {"term": "Repeatability", "def": "Business model feature that brings customers back so lifetime value exceeds acquisition cost."}, {"term": "Core competency", "def": "Unique capability from harmonized resources and skills; invisible and hard to copy (Prahalad and Hamel)."}, {"term": "Oligopoly", "def": "Few firms, differentiated products, high barriers and pricing power, tendency to collude."}, {"term": "Perfect competition", "def": "Many firms, homogeneous products, no barriers, no pricing power."}, {"term": "Porter's Five Forces", "def": "Rivalry, new entrants, substitutes, supplier power, buyer power."}], "examAnswerTips": ["For market type questions, reproduce the table: number of companies, product type, entry barrier, pricing power for monopolistic, oligopolistic, perfect competition; add that oligopolies usually collude.", "For differentiation, define it as a strategy (Nike), then list dimensions in groups (product: quality, features, style, packaging; service: availability, return policy, exchange, loyalty program).", "For moats, list entry barriers and cite Google's 85% search share and network effects; link to pricing power and brand loyalty.", "For Porter, draw the five forces diagram and split horizontal vs vertical forces with one line on each.", "Use 'unfair advantage = cannot be copied or bought' as a crisp opening line."], "quiz": [{"q": "In perfect competition, pricing power is:", "options": ["High", "High with collusion", "Absent", "Moderate"], "answer": 2, "why": "Many firms, homogeneous products, no pricing power."}, {"q": "Which market type has few firms with differentiated products that usually collude?", "options": ["Monopolistic", "Oligopolistic", "Perfect competition", "Monopsony"], "answer": 1, "why": "From the market types table."}, {"q": "Pricing power is the capacity to:", "options": ["Cut prices below rivals", "Increase price without affecting demand", "Set prices by government", "Match competitor prices"], "answer": 1, "why": "Slide definition."}, {"q": "Core competency was propounded by:", "options": ["Michael Porter", "C. K. Prahalad and Gary Hamel", "Eric Ries", "Geoffrey Moore"], "answer": 1, "why": "Prahalad and Hamel."}, {"q": "Which is a vertical force in Porter's model?", "options": ["Threat of substitutes", "Competitive rivalry", "Supplier power", "Threat of new entrants"], "answer": 2, "why": "Vertical forces: supplier and buyer power."}, {"q": "The real competitive advantage, per the slides, is one that:", "options": ["Is cheapest", "Cannot be copied or bought", "Is patented", "Is first to market"], "answer": 1, "why": "Unfair advantage definition."}, {"q": "Which company is cited as a product differentiation and positioning example?", "options": ["Zoho", "Nike", "Practo", "Serum Institute"], "answer": 1, "why": "Nike."}, {"q": "Why is repeatability important?", "options": ["It lowers taxes", "High acquisition cost is recovered via repeat purchases and lifetime value", "It removes competitors", "It increases scale automatically"], "answer": 1, "why": "Repeatability slide."}], "slug": "L13_Competitive_Advantage", "excluded": "Syllabus up to slide 34; crossed-out slides 4, 15–18, 21, 23 and all business-model-innovation slides (35+) excluded."}, {"id": "L14", "title": "Forms of Legal Entities", "oneLiner": "Comparison of Indian business legal forms (proprietorship, partnership, OPC, LLP, private limited, public limited, subsidiary/associate) on liability, ownership, life, tax, compliance and fundraising, with worked bank-recovery examples.", "examRelevance": "Expect: which legal form should a startup choose (private limited) and why angel investors, incubators, accelerators and lenders prefer Pvt Ltd over partnership; pros and cons of the chosen form; numerical on how much a bank recovers on default under limited (Pvt Ltd) vs unlimited (partnership/proprietorship) liability; possibly the partnership income tax exercise.", "sections": [{"heading": "Why the legal form matters", "points": ["Affects liability, taxation and ability to raise funds.", "Also determines longevity and the minimum and maximum number of members.", "Key questions: on liquidation, if assets do not cover liabilities, do owners pay from personal sources? What happens if owners die?", "Forms listed: sole proprietorship, partnership, OPC, LLP, private limited, public limited, co-operative, joint Hindu family business, subsidiary, Section 8 company, trust."]}, {"heading": "Unlimited vs limited liability (master split)", "points": ["Unlimited liability: proprietorship, partnership - creditors can seize owners' personal assets.", "Limited liability: OPC (one member), LLP (2 to any number of partners), Private Limited (2-200 shareholders), Public Limited (min 7 members, 3-15 directors, any number of shareholders).", "Limited liability: owners liable only up to their investment; personal assets insulated; creditors recover only by liquidating the company."]}, {"heading": "Bank recovery worked examples (exam numericals)", "points": ["Proprietorship: default Rs 10M, business assets fetch Rs 6M, remaining Rs 4M recovered from owner's personal assets.", "Proprietorship: loan Rs 1.3M, firm assets Rs 0.6M + personal assets Rs 0.4M = Rs 1.0M recovered; bank loses Rs 0.3M.", "Partnership: default Rs 1.0M, firm assets Rs 0.6M, remaining Rs 0.4M from partners' personal assets; order of partners per deed or mutual decision.", "Pvt Ltd / limited liability: default Rs 1.0M, liquidation fetches Rs 0.6M; bank recovers only Rs 0.6M, cannot touch directors'/members' personal assets.", "Rule: limited liability recovery = company liquidation value only; unlimited = liquidation value + owners' personal assets (up to the debt)."]}, {"heading": "Sole proprietorship", "points": ["Single owner; simplest form; no legal existence separate from owner (same PAN, assets, tax, liability); unlimited liability.", "Full control, keeps all profit, bears all loss; capital only from owner and profits; ends on owner's death.", "Tax: business profit added to owner's income (e.g. Rs 0.6M other + Rs 1.5M business = tax on Rs 2.1M); personal rate ~30% vs corporate 17-22%.", "Formalities: trade license (panchayat or municipal corporation, needs address proof: title deed or rent agreement), PAN, GST (online at gst.gov.in); FSSAI for restaurants; Shops and Establishments Act for shops.", "Pros: easy formation, maximum incentive, secrecy, quick decisions and flexibility.", "Cons: limited capital, limited managerial ability, limited life, unlimited liability, clubbing of income raises tax (above Rs 10 lakh LLP/company rate is lower).", "Suits retailers, grocers, stationery shops, small manufacturing units."]}, {"heading": "Partnership", "points": ["Two or more persons by written or oral agreement; stamped and registered agreement = Partnership Deed; registration optional at state Registrar of Firms.", "If no deed or deed silent, Indian Partnership Act 1932 applies.", "Not a separate legal entity, but separate PAN for tax; firm taxed ~20% of profit; salary and interest to partners deductible.", "Pros: easier than companies, more capital and credit than proprietorship, better judgment and managerial ability, firm taxed separately.", "Cons: no ultimate authority, liable for other partners' actions, limited life (dissolves when a partner dies), unlimited liability.", "Suits small/medium multi-owner businesses with limited capital: SSIs, trade, transport agencies, brokers, CA firms, clinics, law firms."]}, {"heading": "One Person Company (OPC), Companies Act 2013", "points": ["Single member with limited liability; a nominee (natural born Indian citizen) succeeds on death; outside non-shareholding directors allowed.", "Advantage: one individual can run a limited liability company (Pvt Ltd needs at least two).", "Paid-up capital Rs 1 lakh min to Rs 50 lakh max (per slide); cannot transfer shares or invite public subscription.", "Formation steps (same for Pvt Ltd): 1 DSC, 2 DIN, 3 name approval (RUN), 4 MoA, AoA and documents, 5 file with MCA; RoC issues certificate of incorporation.", "vs proprietorship: limited vs unlimited liability; company tax bracket vs individual; nominee succession vs court; annual report and audit vs no annual returns.", "Motivations: full control, uninterrupted existence, easy transferability, better borrowing (lenders prefer company), can own property as artificial person.", "Conversion to Pvt Ltd: voluntary (after min 2 years); since 1 Apr 2021 no forced conversion on capital/turnover; done to add co-founder or raise outside equity."]}, {"heading": "Limited Liability Partnership (LLP), LLP Act 2008", "points": ["Combines partnership flexibility with limited liability at lower compliance cost than Pvt Ltd.", "Internal management by mutual LLP agreement; min 2 partners incl. 2 designated partners; no maximum.", "Preferred by SMEs, service sector and professionals globally.", "vs Pvt Ltd: LLP agreement (or Schedule 1) instead of MoA/AoA; transfer allowed but transferee not automatically partner; common seal optional; easy dissolution; converting to company requires winding up LLP."]}, {"heading": "Private Limited Company", "points": ["Voluntary association of 2 to 200 members; 2 to 15 directors; artificial juridical person.", "Liability limited to ownership; creditors cannot touch owners' personal assets.", "Share transfer restricted to members; cannot invite public subscription, but can invite investors and offer equity.", "Keeps control within a limited circle, maintains privacy; managed by Board of Directors; common seal compulsory.", "Pros: continuity of existence, limited liability, shares transferable with formalities (can add directors/shareholders), fewer restrictions than public ltd (no statutory general meeting or statutory report), no cap on managerial remuneration.", "Cons: shares not freely transferable, cannot invite public, undemocratic control, more formalities for office change or dissolution than LLP.", "Can be converted into LLP or public limited company."]}, {"heading": "Public Limited Company and Pvt vs Public", "points": ["Independent artificial juridical person, perpetual succession, shares easily transferable, raises share capital from public.", "Members: public min 7, unlimited max; Pvt min 2, max 200.", "Directors: public min 3, Pvt min 2; both max 15.", "Minimum capital: none for either (no MCA fees up to Rs 15 lakh capital).", "Public can invite public to subscribe; Pvt cannot.", "Managerial remuneration: public max 11% of annual net profit; Pvt no restriction."]}, {"heading": "Crisp comparison of forms", "points": ["Proprietorship: 1 owner, unlimited liability, limited life, owner and firm income added, no shares, minimal compliance, weakest fundraising.", "Partnership: 2-20 members, unlimited liability, limited life, firm taxed separately, no shares, deed-based compliance, limited fundraising.", "OPC: 1 member, limited liability, perpetual, cannot issue shares, annual audit, better borrowing than proprietorship.", "LLP: 2 to any partners, limited liability, perpetual, cannot issue shares, lower compliance than company, no equity issue to investors.", "Pvt Ltd: 2-200 members, limited liability, perpetual, can issue shares within limited shareholders (investors), moderate compliance, best for startup fundraising.", "Public Ltd: 7 to any, limited liability, perpetual, can issue shares to public, highest compliance."]}, {"heading": "Subsidiary and associate", "points": ["Subsidiary: owned by a parent/holding company (or companies and individuals); wholly owned if by one company; may be any legal form; many foreign firms have Indian subsidiaries.", "Associate: parent holds significant but not majority stake, commonly 20% to 50% of voting shares."]}, {"heading": "Balance sheet and liquidation logic", "points": ["Example balance sheet: total assets Rs 1630 (2022) and Rs 1912 (2023); equity, reserves, preference equity, trade payables, short and long-term bank loans.", "On liquidation asset value should cover liabilities; legal form decides whether owners must fund any shortfall personally."]}], "cases": [{"name": "Gurtej Singh Sandhu", "crux": "Inventor in thin-film processes and semiconductor fabrication; method of coating chips with titanium without oxygen exposure, used by most memory-chip makers; over 2,500 patent applications."}, {"name": "Patagonia", "crux": "Purpose-driven 'Don't buy our products' marketing: educated customers on textile ecological impact, sold long-lasting pricey jackets, taught repairs, exchanged and recycled garments; profit rose 30%; now held by a trust."}, {"name": "AB Firm partnership tax exercise", "crux": "Firm profit Rs 20 lakh, salaries A 3L and B 5L (deductible), side income A 5L and B 7L; firm tax 20%, personal 30%. If 20L is before salaries: firm pays 20% of 12L = 2.4L, A pays 30% of 8L = 2.4L, B pays 30% of 12L = 3.6L; total 8.4L."}, {"name": "Product adoption categories", "crux": "Slide lists customer types: innovator, early adopter, early majority, late majority, laggard."}], "keyTerms": [{"term": "Unlimited liability", "def": "Owners' personal assets can be used to pay business debts (proprietorship, partnership)."}, {"term": "Limited liability", "def": "Owners liable only up to their investment; personal assets insulated (OPC, LLP, Pvt Ltd, Public Ltd)."}, {"term": "Artificial juridical person", "def": "Company recognised in law as a person separate from owners; can own property, sue and be sued."}, {"term": "Partnership Deed", "def": "Stamped and registered written partnership agreement defining rights, duties, capital and liabilities."}, {"term": "OPC", "def": "One Person Company: single member limited liability company with a nominee successor."}, {"term": "LLP", "def": "Limited Liability Partnership: partnership flexibility plus limited liability, low compliance."}, {"term": "Private Limited Company", "def": "2-200 members, 2-15 directors, limited liability, restricted share transfer, no public subscription."}, {"term": "Public Limited Company", "def": "Min 7 members, 3-15 directors, shares freely transferable, can invite public subscription."}, {"term": "MoA / AoA", "def": "Memorandum of Association defines activities; Articles of Association define procedures."}, {"term": "DSC, DIN, RUN", "def": "Digital Signature Certificate, Director Identification Number, Reserve Unique Name - incorporation steps."}, {"term": "Associate company", "def": "Company in which another holds a significant non-majority stake, commonly 20-50% voting shares."}, {"term": "Perpetual succession", "def": "Entity continues regardless of death or change of owners."}], "examAnswerTips": ["Recommend Private Limited for a scalable startup and justify: limited liability, separate legal entity, perpetual succession, can issue equity to angels/VCs/accelerators, shares transferable with formalities, lenders prefer companies, lower corporate tax (17-22%) than personal 30%.", "Contrast with partnership explicitly: unlimited and joint liability, dissolves on a partner's death, cannot issue shares, no ultimate authority - hence investors and lenders avoid it.", "Give pros AND cons of Pvt Ltd: restricted share transfer, no public issue, more compliance and formalities, undemocratic control.", "For bank recovery numericals, state: Pvt Ltd - bank gets only liquidation value; partnership/proprietorship - liquidation value plus personal assets until the debt is paid; compute shortfall and who bears it.", "Use a comparison table: liability, members, life, tax, compliance, ability to raise funds.", "Cite numbers exactly: Pvt Ltd 2-200 members and 2-15 directors; Public min 7 members and 3 directors; associate 20-50%."], "quiz": [{"q": "A Pvt Ltd company defaults on a Rs 1.0M loan; liquidation fetches Rs 0.6M. How much does the bank recover?", "options": ["Rs 1.0M", "Rs 0.6M", "Rs 0.4M", "Rs 0"], "answer": 1, "why": "Limited liability: only liquidation value; directors' personal assets cannot be sold."}, {"q": "Same default (Rs 1.0M, firm assets Rs 0.6M) in a partnership with ample personal assets. Bank recovers:", "options": ["Rs 0.6M", "Rs 0.4M", "Rs 1.0M", "Rs 0.2M"], "answer": 2, "why": "Unlimited liability: remaining Rs 0.4M comes from partners' personal assets."}, {"q": "Membership limits of a private limited company:", "options": ["1 to 50", "2 to 200", "7 to unlimited", "2 to 20"], "answer": 1, "why": "Not less than two and not more than two hundred members."}, {"q": "Minimum members for a public limited company:", "options": ["2", "3", "7", "15"], "answer": 2, "why": "Public limited needs a minimum of seven members."}, {"q": "Which form has limited liability but cannot issue shares and has lower compliance than a company?", "options": ["Partnership", "LLP", "Public Ltd", "Proprietorship"], "answer": 1, "why": "LLP combines partnership flexibility with limited liability at lower compliance cost."}, {"q": "In an OPC, who succeeds the sole member on death?", "options": ["Court-appointed heir", "The nominee", "The RoC", "Company is dissolved"], "answer": 1, "why": "A nominee who is a natural born Indian citizen becomes successor."}, {"q": "Managerial remuneration cap in a public limited company:", "options": ["5% of net profit", "11% of annual net profit", "No restriction", "20% of revenue"], "answer": 1, "why": "Should not exceed 11% of annual net profit; Pvt Ltd has no restriction."}, {"q": "Which law governs partnerships when there is no deed?", "options": ["Companies Act 2013", "LLP Act 2008", "Indian Partnership Act 1932", "Shops and Establishments Act"], "answer": 2, "why": "Provisions of the Indian Partnership Act 1932 apply."}, {"q": "An associate company is typically one where the parent holds:", "options": ["100%", "51-100%", "20-50% of voting shares", "Below 5%"], "answer": 2, "why": "Common threshold is 20% to 50% of voting shares."}, {"q": "First step to form an OPC or Pvt Ltd:", "options": ["File MoA with MCA", "Apply for Digital Signature Certificate", "Get name approval (RUN)", "Apply for GST"], "answer": 1, "why": "Steps: DSC, DIN, RUN, MoA/AoA, file with MCA."}], "slug": "L14_Legal_Entities", "excluded": "Crossed-out slides 49–52, 54–56 excluded."}, {"id": "L15", "title": "Funding a New Venture", "oneLiner": "Forms and sources of capital, seniority in liquidation, dilution across stages, bootstrapping, crowdfunding, incubators, accelerators, angels and VCs, fund requirement estimation, term sheets, due diligence and preference share terms.", "examRelevance": "One full question is announced on Financing a New Venture: expect sources and stages of funding, debt vs equity vs preference shares, dilution/shareholding calculations, liquidation preference and participation numericals, term sheet and due diligence contents, and working capital/project cost estimation.", "sections": [{"heading": "Forms of capital and uses of money", "points": ["Forms: equity (ownership), preference shares (equity or debt flavour or both), debt (loan with interest, repaid no matter what), grant (no covenant).", "Startup needs money for infrastructure, working capital, sales promotion, brand building, logistics, post-sales service, employee benefits, website/app, hiring, legal, licences, marketing, office.", "Uses of capital = assets (cash, receivables, inventory, land, building, machinery). Sources = equity and liabilities (equity capital, reserves, preference capital, trade payables, short- and long-term debt).", "Why external money: unlimited risk, capital investment, cash flow challenges, long product development; growth needs large funds; external money somewhat reduces risk."]}, {"heading": "Equity capital basics", "points": ["Authorized capital: maximum equity approved by Registrar of Companies. Paid-up capital: extent subscribed. Each share has face (par) value, e.g. Rs 10.", "Paid-up Rs 2,00,000 at face value Rs 10 = 20,000 shares. Shares give ownership and voting rights.", "Example: 2 lakh shares (Rs 20 lakh) held A 50,000 (25%), B 80,000 (40%), C 70,000 (35%).", "To give investor 20%, create new shares: total = 2,00,000 / 0.8 = 2,50,000; investor gets 50,000; A 20%, B 32%, C 28%. Founders' share count stays the same."]}, {"heading": "Sources of funds (list)", "points": ["Bootstrapping (own sources incl. credit cards), friends and family, crowdfunding, startup competitions, impact investors (Villgro), incubators, accelerators (Surge by Sequoia).", "Angel investors, venture capitalists, private equity, bank loans, advance from future customers, startup credit card (Laghu Udhyami card, IDBI).", "Government institutions: DSIR, SIDBI, NABARD, MSME (NSIC). Government funds: India Aspiration Fund, SIDBI SMILE, Mudra; grants via startupindia.gov.in.", "Sources of equity: founders, incubator, accelerator, HNIs, impact investors, business angels, VC funds, PE funds."]}, {"heading": "Stages of funding and dilution", "points": ["Life cycle: develop idea and business model (bootstrap, friends and family), build product (seed, incubators, angels), customer validation (early-stage VC), repeatable model and scale (mid/late VC, debt, strategic investors), exit via IPO.", "Series A is the first VC round, then B, C, D. Valuation rises and risk perception falls as traction grows: idea, prototype, proof of concept, infra, seed marketing, go-to-market.", "Dilution: reduction in founders' holding with equity funding. Early raising means higher dilution (lower valuation); delay may mean loss of opportunity.", "Raising Rs 1M: at value 3M gives 25%, at 4M gives 20%, at 9M gives 10% (values act as pre-money).", "Ready to raise when: promising concept, validated by early customers, and sure extra fund takes you to next phase. Raise enough only for next proof point (de-risking)."]}, {"heading": "Security and seniority", "points": ["Loan security: hypothecation (asset stays with borrower), mortgage (immovable property), lien (creditor retains asset until paid), pledge (movable property delivered to lender), personal guarantee.", "Primary security: charge on assets funded by the loan; collateral: charge on other assets. Seniority depends on secured vs unsecured and primary vs subordinated.", "Liquidation order: secured creditors, then unsecured creditors and employees, then preference shareholders, equity holders last. Same-ranking securities are pari passu.", "Ranking slide: secured (government claims, collateral-secured bank loans, subordinated), unsecured (public deposits, bonds, trade creditors), mezzanine (preference, seed), equity (equity, subsidy, grant).", "Loans: long-term for capital assets (life over a year), short-term for working capital."]}, {"heading": "Debt vs equity vs preference shares", "points": ["Debt: repayment with interest and charges, no ownership or dilution, covenants, security on assets plus collateral, claim senior to shareholders.", "Equity: no interest or repayment, dilution, part ownership, mentoring and supervision, no security; exit through IPO or acquisition. Cons: dividend, investor interference.", "Preference shares: fixed dividend paid before equity and accrued; may be convertible or redeemable; no voting rights; paid before equity in liquidation; limited upside.", "Equity shares: dividend from surplus at board's discretion, not accrued; voting rights; buy-back possible; unlimited upside. Grant: no cost, often no dilution, non-returnable.", "Long-term loan repaid in instalments; short-term loan repaid on demand. Investors prefer preference shares or convertible debt."]}, {"heading": "Bootstrapping and crowdfunding", "points": ["Bootstrapping: funds from sources other than formal investors and lenders: personal savings, cost cutting, shared office, cheapest travel, interns, freelancers, used machines, advance payments, grants.", "Crowdfunding: raising money from many individuals via online platform. Types: reward-based, equity-based (not legal in India), lending-based, pre-order, donation/social, peer-to-peer lending.", "Pros: easy, crowd does not interfere, usually no dilution, product validation. Cons: needs social dimension and story, early idea disclosure risks copycats, not for B2B.", "SEBI has no formal crowdfunding framework; donation, reward and P2P are outside SEBI (P2P may be under RBI). Fees mostly 3-5%, up to 30%; Ketto 5-8%; Milaap biggest in India."]}, {"heading": "Incubators and accelerators", "points": ["Incubation: keeping something in the right conditions to mature; provides infrastructure, interns, validation, IP filing and seed funds.", "Accelerator: fixed short programs of 3-6 months in cohorts with mentorship, guidance, networking and small funds; ends with Demo Day pitch to investors.", "Accelerators may take 3-8% equity; Y Combinator and TechStars accept 1-3% of applicants and focus on teams.", "Sequoia Surge (2019): 10-20 startups twice a year, $1-2M each. IIT Kharagpur RMSoEE with Z21 Ventures: Rs 25 lakh seed plus Rs 25 lakh later."]}, {"heading": "Angels and VCs", "points": ["Angel: individual with surplus funds investing personal capital at early, high-risk stage for ownership; experienced, mentors closely, connects to market and investors. Often in groups.", "Angels typically invest about Rs 2-10 million; VCs usually above Rs 50 million per deal.", "VC: private equity investor pooling funds from others into high-growth companies for equity; VCs are part of a firm, more formal and meticulous due diligence, prefer track record.", "Investment stages: deal origination, screening, evaluation, structuring, negotiation and agreement.", "Angel rejection reasons: outside geography, long pre-revenue phase, unattractive sector, limited scalability, weak business model, too large funding need, weak team, no tax relief eligibility."]}, {"heading": "Estimating fund requirement", "points": ["Fixed capital: land and building 10, machinery 100, other (transformer, licences, road, disposal) 20, trial production 5, contingency 10 = 145.", "Working capital by turnover method: 25% of turnover (200 gives 50). Fixed 145 + WC 50 = 195 (slide prints 190).", "Holding period method: raw material 600 x 1/12 = 50; WIP 720 x 0.5/12 = 30; finished goods 840 x 1.5/12 = 105; receivables 1200 x 2.5/12 = 250; total 435.", "Less creditors 540 x 1/12 = 45, so net WC = 390 (slide prints 370). Founders bring margin money; project report states need for fund and sources (equity, debt, grants)."]}, {"heading": "Term sheet and due diligence", "points": ["Term sheet: formal, non-binding offer after a successful pitch. Minimum: pre-money valuation, amount, form of investment, use of proceeds, term and mode of exit; plus exclusivity/no-shop clause.", "Terms negotiable with limits; base deals on future market; be consistent, do not bluff, leave ego out; keep short time horizon.", "Due diligence: legal, financial and strategic review of structure, history, contracts and documents; tedious and costly; key is preparation and cooperation.", "Art (what, how, when to ask; search and destroy) and science (question list, data system, quantitative risk analysis).", "Looks for: overdue tax, inadequate systems, related-party transactions, over-reliance on customers/suppliers, overdue or unrecorded liabilities, imminent major expenditure."]}, {"heading": "Liquidation preference, participation, anti-dilution", "points": ["Liquidation preference: how proceeds of a liquidation event (trade sale, IPO, dissolution) are distributed; none, 1X (get investment back) or nX (n times investment).", "Participating: after preference payout, investor also takes pro-rata share of the remainder. Non-participating: only the preference amount.", "Anti-dilution (preferred stock only): if later shares are issued at lower price, earlier investor gets extra shares so average price is not above new price; may need to subscribe to new round.", "Drag-along: investors can compel founders and others to vote for a sale or merger. Later, convertibles convert to equity and payout follows percentage holding."]}], "cases": [{"name": "Peter Thiel and Facebook", "crux": "$500,000 in 2004 sold eight years later for over $1 billion."}, {"name": "Airbnb 2008", "crux": "Sought $150,000 for 10% and all investors refused; later valued $31 B and now over $100 B. Every investor has a great regret."}, {"name": "Liquidation waterfall", "crux": "Claims: bank 1000, second lien 200, trade creditors 200, unsecured 300, preference 500 (total 2200). Proceeds 1500 leave unsecured 100, preference 0; 1300 leaves trade 100; 2500 leaves equity 300."}, {"name": "Uncle and angel rounds", "crux": "You 60,000 and partner 40,000 shares; uncle gets 42,857 for 30% (total 1,42,857); angel 35,714 for 20% (total 1,78,571); you fall 60% to 42% to 33.6%."}, {"name": "BA invests 50M for 25%, exit at 100M", "crux": "Post-money 200M, pre-money 150M. No preference: BA 25M; 1X non-participating: 50M; 1X participating: 62.5M; 2X participating: 100M and founders nil."}, {"name": "2X participating at higher exits", "crux": "Exit 400M: BA 100 + 75 = 175M, founders 225M. Exit 1000M: BA 100 + 225 = 325M, founders 675M."}, {"name": "Participating 1X, 50M at 50M pre-money, exit 250M", "crux": "Investor gets 50M + 50% of 200M = 150M; entrepreneur 100M. With plain conversion each would get 125M."}, {"name": "Angel-1 and Angel-2 rounds", "crux": "Pre 5 lakh plus 10 lakh gives founders 33.33%. Later pre 10 crore plus 5 crore gives new investor 33.33% (1,500 new shares on 3,000)."}, {"name": "BYJU'S", "crux": "No early investors let the team patiently build content for grades 8-12 before launching in 2015."}, {"name": "Nestaway", "crux": "Valued Rs 1800 crore with Rs 700 crore raised, sold for Rs 90 crore; co-founder filed FIR alleging lead investor pushed a distress sale."}], "keyTerms": [{"term": "Authorized capital", "def": "Maximum equity capital a company may issue, approved by the Registrar of Companies."}, {"term": "Paid-up capital", "def": "Equity capital actually subscribed and paid."}, {"term": "Dilution", "def": "Reduction in percentage holding of existing shareholders when new shares are issued."}, {"term": "Seniority", "def": "Order of repayment in liquidation; senior claims are paid before junior ones."}, {"term": "Pari passu", "def": "Securities of equal seniority ranking side by side."}, {"term": "Collateral", "def": "Assets other than those financed by the loan offered as security."}, {"term": "Hypothecation", "def": "Asset stays with borrower as security without transferring possession."}, {"term": "Pledge", "def": "Movable property physically delivered to lender until repayment."}, {"term": "Mezzanine", "def": "Hybrid/quasi-equity finance (e.g. preference shares) senior to equity but junior to secured debt."}, {"term": "Term sheet", "def": "Non-binding formal offer stating basic investment terms."}, {"term": "Due diligence", "def": "Legal, financial and strategic investigation of the company by investors."}, {"term": "Liquidation preference", "def": "Right of preferred holders to receive 1X or nX their investment before common holders."}, {"term": "Participating preferred", "def": "Gets preference amount plus pro-rata share of remaining proceeds."}, {"term": "Anti-dilution", "def": "Protection giving earlier preferred investors extra shares if a later round is at lower price."}, {"term": "Drag-along", "def": "Right of investors to compel other shareholders to approve a sale or merger."}, {"term": "Demo Day", "def": "Final event of an accelerator where startups pitch to investors."}, {"term": "Bootstrapping", "def": "Funding with own and informal resources without formal investors or lenders."}], "formulas": [{"name": "Post-money total shares", "expr": "New total shares = Existing shares / (1 - investor %)", "note": "2,00,000 / 0.8 = 2,50,000; investor gets the difference."}, {"name": "Holding %", "expr": "Shares held / Total shares", "note": "Founders' share count unchanged when new shares are created."}, {"name": "Post and pre-money", "expr": "Post-money = Investment / investor %; Pre-money = Post-money - Investment", "note": "50M / 0.25 = 200M; pre 150M."}, {"name": "Non-participating nX payout", "expr": "Investor = min(proceeds, n x investment) (or converts if better)", "note": "Remainder to common holders."}, {"name": "Participating nX payout", "expr": "Investor = n x investment + holding% x (proceeds - n x investment)", "note": "1X, 25%, exit 100M: 50 + 12.5 = 62.5M."}, {"name": "Working capital (holding period)", "expr": "Sum of annual cost x holding months / 12 for RM, WIP, FG, receivables - creditors", "note": "Example nets to 390."}, {"name": "Working capital (turnover method)", "expr": "WC = 25% of turnover", "note": "Turnover 200 gives WC 50."}, {"name": "Project cost", "expr": "Fixed capital + Working capital", "note": "Funded by founders' margin money plus debt/equity/grants."}], "examAnswerTips": ["Structure a financing answer: need for funds (fixed + working capital), forms of capital, sources by stage, pros and cons of debt vs equity, government schemes, term sheet and due diligence.", "Draw the funding life-cycle: bootstrap, friends and family, seed/incubator, angels, early VC, later VC/debt/strategic, IPO; note valuation rising and dilution falling.", "In liquidation waterfalls pay strictly by seniority: secured, unsecured, preference, equity.", "For preference numericals compute post-money, then apply preference, then participation on the remainder; check founders' residue.", "Remember equity crowdfunding is not legal in India and term sheets are non-binding.", "Trap: percentage holding alone can mislead; a 2X participating preference can wipe founders out at low exits.", "Trap: slide 15 table mislabels B and C percentages; use 25/40/35 pre and 20/32/28 post."], "quiz": [{"q": "In liquidation, who is paid last?", "options": ["Secured creditors", "Unsecured creditors", "Preference shareholders", "Equity shareholders"], "answer": 3, "why": "Equity holders come last."}, {"q": "Founders hold 2,00,000 shares and give an investor 20% via new shares. New total shares?", "options": ["2,40,000", "2,50,000", "2,20,000", "2,00,000"], "answer": 1, "why": "2,00,000 / 0.8 = 2,50,000."}, {"q": "BA invests 50M for 25%. Pre-money valuation?", "options": ["200M", "150M", "100M", "50M"], "answer": 1, "why": "Post 200M minus 50M."}, {"q": "Same BA, 1X participating preference, company sold for 100M. BA receives:", "options": ["25M", "50M", "62.5M", "100M"], "answer": 2, "why": "50 + 25% of 50 = 62.5M."}, {"q": "Same BA, 2X participating, sold for 400M. BA receives:", "options": ["100M", "175M", "225M", "325M"], "answer": 1, "why": "100 + 25% of 300 = 175M."}, {"q": "Claims: bank 1000, second lien 200, trade creditors 200, unsecured 300, preference 500. Proceeds 2500. Equity holders get:", "options": ["0", "300", "500", "800"], "answer": 1, "why": "2500 - 2200 = 300."}, {"q": "Which type of crowdfunding is not legal in India?", "options": ["Reward-based", "Donation-based", "Equity-based", "Pre-order"], "answer": 2, "why": "Equity crowdfunding not legal; SEBI has no framework."}, {"q": "Which is a minimum term in a term sheet?", "options": ["Employee birthdays", "Pre-money valuation", "Office layout", "Audit fee"], "answer": 1, "why": "Pre-money valuation, amount, form, use of proceeds, exit."}, {"q": "A term sheet is:", "options": ["Binding on investors", "Non-binding on investors", "A loan agreement", "A government licence"], "answer": 1, "why": "Conditions are non-binding."}, {"q": "Movable property physically delivered to lender as security is a:", "options": ["Mortgage", "Hypothecation", "Pledge", "Lien"], "answer": 2, "why": "Pledge involves physical delivery."}, {"q": "Raising Rs 1M when pre-money value is Rs 4M gives the angel:", "options": ["25%", "20%", "10%", "4%"], "answer": 1, "why": "1 / (4 + 1) = 20%."}, {"q": "Working capital by turnover method for turnover 300 is:", "options": ["50", "62.5", "75", "100"], "answer": 2, "why": "25% of 300 = 75."}], "slug": "L15_Funding", "excluded": "Syllabus up to slide 122; crossed-out slides 7, 16, 70, 71, 78, 79, 87 excluded."}, {"id": "L16", "title": "Marketing for Startups", "oneLiner": "Pricing models, marketing definitions, the marketing/sales funnel and customer journey, segmentation-targeting-positioning, TAM/SAM/SOM, and digital marketing models for startups.", "examRelevance": "Expect application questions: define the market segment, targeting, positioning and pricing model of a given startup; trace a customer journey through the sales funnel; explain five pricing models with examples; explain five digital marketing models with examples; estimate TAM/SAM/SOM.", "sections": [{"heading": "Ten pricing models", "points": ["Cost-plus: cost of production + fixed markup. Simple, covers costs, guarantees margin; ignores demand, willingness to pay, competitors.", "Value-based: price by perceived customer value, not cost. Higher margins if valued; hard to assess perception, risky (e.g. luxury brands, Daraprim).", "Competitive: price at, above or below competitors. Easy in crowded markets; price wars, ignores own value proposition.", "Penetration: low initial price to gain share, raise later. Fast share and recognition; low early profit, hard to raise prices.", "Skimming: high launch price for early adopters, lowered over time (e.g. new iPhone). Max early margins; deters price-sensitive buyers, invites cheaper rivals.", "Freemium: basic free, charge for premium features.", "Subscription: periodic recurring fee for continuous access.", "Dynamic: real-time supply/demand or behaviour based (e.g. surge pricing in ride-sharing).", "Bundle: multiple products together at reduced price vs individually.", "Pay-what-you-want: customer chooses price. Each model suits different objectives, audiences and products."]}, {"heading": "Trend-based business models", "points": ["Trends (technology, fashion, social, lifestyle, economic, environmental) create opportunities for new winning ventures.", "Those ahead of or at the forefront of a trend enjoy natural advantages; forecasting trends matters."]}, {"heading": "What marketing is", "points": ["Starts when the pain point is identified and continues while the company is a going concern; relevant at every phase: idea, define, prototype, validation, refine, go-to-market, commercial operation, growth, sustain.", "Building relationships via strong brand, reaching more audience, acquiring and retaining satisfied customers, establishing trust, building loyal base.", "'The best product does not always win. The best marketing does' (Steve Denning).", "Social definition: societal process of obtaining needs and wants through creating, offering and freely exchanging products of value.", "Drucker: aim of marketing is to make selling superfluous - product fits customer and sells itself.", "AMA: planning and executing conception, pricing, promotion, distribution of ideas, goods, services to create satisfying exchanges.", "Kotler: art and science of choosing target markets and getting, keeping, growing customers by creating, delivering, communicating superior value.", "Sales converts goods into cash; marketing is selling through a sustainable, satisfying customer relationship."]}, {"heading": "Marketing as a 7-step process", "points": ["1 Convey the value proposition to the market segment.", "2 Create value for customers, perceived and real.", "3 Build strong relationships; story resonates with customer persona.", "4 Understand changing needs and choices.", "5 Refine or redesign products for higher perceived value.", "6 Build strong brand via emotional connection; premium brand equity, pricing power, recall.", "7 Create and sustain value for stakeholders."]}, {"heading": "Marketing / sales funnel and customer journey", "points": ["Stages: Awareness, Interest, Consideration, Intent, Evaluation, Purchase, Reference (virality).", "Population narrows: people at large/whole market, market segment, prospects, lead nurture, sales, virality.", "Customer journey: imaginary channel walking a prospect from awareness to interest to purchase to spreading favourable word.", "Journey begins before someone is a prospect: advertise for awareness; some know, some become prospects, some buy, some become evangelists.", "Collect data at each stage to find causes of dropout; reduce friction, deliver consistent value, build trust at every touchpoint."]}, {"heading": "Segmentation, targeting, positioning", "points": ["Three steps: market segmentation, target market/niche, product or service positioning (plus influencer marketing and pre-launch hype for escape velocity).", "Mission links to market: identify a pain (SEGMENT), understand needs (EMPATHIZE), position the offer (VALUE PROPOSITION).", "Define a customer persona: characteristics, taste, choices, behaviour, aspirations, pains; this homogeneous group, even if geographically spread, is the segment.", "Persona then drives product customization, awareness media, sales/delivery channel, promotion and loyalty (positioning).", "Segment: subset of market with similar likes, tastes, aspirations, pains, needs, affordability, seeking similar solutions.", "Segmentation: dividing a heterogeneous market into homogeneous subgroups with similar needs for a particular product.", "Segment is product specific: same village segments differently for detergent, soap, male dresses, insecticide or designer jewelry."]}, {"heading": "Why segment", "points": ["Address a small relevant group and exclude non-customers; identify and define unmet pain.", "Understand market size, growth, existing competitor solutions, features of a better solution.", "Assess entry barriers and competition; develop a competitive, superior value proposition.", "Check the segment values the solution and will buy at the desired price.", "Choose channels to reach, deliver and serve; save money on awareness, logistics and delivery."]}, {"heading": "TAM, SAM, SOM", "points": ["TAM: total demand in the entire market (all who could potentially buy, e.g. all smartphone buyers).", "SAM: subset of TAM within your reach that you can realistically serve.", "SOM: portion of SAM you can practically capture.", "Uses: fair market-size assessment, meaningful sales projections, startup valuation, estimating investor returns."]}, {"heading": "Digital marketing models", "points": ["Content marketing: useful, relevant content that informs purchase decisions without asking to buy; builds engagement and loyalty; costs 62% less than traditional marketing, 3x leads.", "SEO: keyword-relevant content, site optimization and links so website ranks on first page of search results.", "Pay-per-click: paid text, image, video ads; pay each time someone clicks through to your site.", "Social media marketing: paid brand content (text, images, video) on LinkedIn, YouTube, Facebook, Instagram to reach specific audiences.", "E-mail marketing: use collected emails to educate, engage, nurture and get repeat purchases and feedback.", "Affiliate marketing: links on third-party websites driving signups and subscriptions; mostly paid.", "Influencer marketing: YouTubers and popular media show products positively; replacing celebrities as people trust influencers as 'one of us'; mostly paid."]}, {"heading": "Marketing tools (traditional and digital)", "points": ["Branding, messaging, advertising, online presence, content marketing, PR, selling, market research, influencer marketing, pricing, social media, customer engagement, customer experience.", "Omnichannel: integrated channels give a consistent brand experience (e.g. buy online, pick up in store); differs from multichannel in the customer journey."]}], "cases": [{"name": "TataCliq Luxury", "crux": "Luxury branding lets firms charge exorbitant prices disconnected from cost of production - value-based pricing."}, {"name": "Turing Pharmaceuticals / Daraprim (2015)", "crux": "Martin Shkreli raised Daraprim from $13.50 to $750 per tablet (5,000%) - monopoly enables value-based pricing."}, {"name": "Apple iPhone", "crux": "High launch price for early adopters, reduced as demand falls and newer models launch - skimming pricing."}, {"name": "Nykaa (Falguni Nayar)", "crux": "Valued ~Rs 1,00,000 crore ($16B); 1200+ brands plus own lines; omnichannel marketing, content marketing via YouTube and 'Nykaa beauty book' blog without selling there, event marketing with Femina Miss India."}, {"name": "Maggi Noodles", "crux": "Marketing as science, art and philosophy: pain point, segmentation, product-market fit, distribution, engagement, emotional connection, brand recall vs ITC, Marico, Unilever, Patanjali, Nissin."}, {"name": "10 carat gold jewelry", "crux": "Rs 1 crore pilot; instead of visiting every household, segment by income and women aged 18-60. Of 5,000 families: 800 middle income, minus 400 male-only and 280 male-and-widow, leaves 120 target families; brochures, demo, discount close deals in a week."}, {"name": "Ather Energy TAM/SAM/SOM", "crux": "TAM all Indian 2-wheelers ~Rs 2,00,000 Cr (20M units); SAM premium urban scooters in Tier-1/2 cities ~Rs 13,500 Cr (900K); SOM 10-12% share in launch cities ~Rs 1,500 Cr (100K) in 24 months."}, {"name": "Huggies", "crux": "Content marketing: used research that hugs strengthen babies' vitals and bonding to build a 'hug your baby' narrative for new mothers, winning loyal customers."}, {"name": "Baggit (founder named Nina Lehi on slide)", "crux": "Started bag business in 1990 at 18 after dropping out; eco-friendly bags for modern Indian women; influencer campaign where bloggers carried bags at an event and explained their choice."}, {"name": "Ryan Toys Review", "crux": "Child YouTuber earning $22M (2018, Forbes No. 1) and nearly $30M a year reviewing and unboxing toys - power of influencer marketing."}, {"name": "The Collective", "crux": "Cited as a super-premium brand example under segmentation, targeting and positioning."}], "keyTerms": [{"term": "Market segment", "def": "Subset of the market with similar needs, tastes, pains, aspirations and affordability for a specific product."}, {"term": "Segmentation", "def": "Dividing a heterogeneous market into homogeneous subgroups with similar needs for a product."}, {"term": "Targeting", "def": "Choosing the segment/niche to serve."}, {"term": "Positioning", "def": "Placing the offer so it resonates with the target audience via the value proposition and builds loyalty."}, {"term": "Customer persona", "def": "Profile of the customer's characteristics, taste, behaviour, aspirations and pains."}, {"term": "Sales funnel", "def": "Awareness, Interest, Consideration, Intent, Evaluation, Purchase, Reference."}, {"term": "TAM / SAM / SOM", "def": "Total addressable, serviceable addressable and serviceable obtainable market."}, {"term": "Skimming pricing", "def": "High launch price lowered over time."}, {"term": "Penetration pricing", "def": "Low launch price to gain share, raised later."}, {"term": "Freemium", "def": "Basic free, premium paid."}, {"term": "Omnichannel", "def": "Integrated channels for a consistent brand experience across store and online."}, {"term": "Content marketing", "def": "Informative content that helps buyers decide without explicitly selling."}, {"term": "PPC", "def": "Pay-per-click advertising; pay each time an ad is clicked."}], "examAnswerTips": ["For segment/targeting/positioning questions, apply rather than define: describe a persona (age, income, location, pain, behaviour), narrow down like the gold jewelry funnel, state the target niche, then a positioning line tied to the value proposition.", "Add a TAM/SAM/SOM estimate with numbers (Ather style) to show market size thinking.", "Choose a pricing model and justify against product type and objective (e.g. freemium or subscription for apps, skimming for innovative tech, penetration for share grab); give pros and cons.", "For five pricing or five digital marketing models: name, one-line description, one example each (iPhone skimming, ride-share surge dynamic, Nykaa/Huggies content, Baggit/Ryan influencer).", "Trace the customer journey through every funnel stage (Awareness to Reference) with a specific marketing action at each and how you reduce dropout.", "Quote Drucker or Kotler briefly to frame definitions."], "quiz": [{"q": "Apple launching iPhones at a high price and cutting it later is:", "options": ["Penetration pricing", "Skimming pricing", "Cost-plus pricing", "Bundle pricing"], "answer": 1, "why": "High initial price for early adopters, lowered over time."}, {"q": "Surge pricing in ride-sharing is an example of:", "options": ["Dynamic pricing", "Competitive pricing", "Freemium", "Pay-what-you-want"], "answer": 0, "why": "Prices adjusted on real-time supply and demand."}, {"q": "Main disadvantage of cost-plus pricing:", "options": ["Hard to calculate", "Ignores demand and willingness to pay", "Leads to losses", "Requires monopoly"], "answer": 1, "why": "Doesn't account for demand, willingness to pay or competitors."}, {"q": "Correct funnel order:", "options": ["Interest, Awareness, Purchase, Evaluation", "Awareness, Interest, Consideration, Intent, Evaluation, Purchase, Reference", "Awareness, Purchase, Interest, Reference", "Consideration, Awareness, Intent, Purchase"], "answer": 1, "why": "As on the funnel slide."}, {"q": "SOM represents:", "options": ["All potential buyers", "Market you can serve", "Portion you can practically capture", "Competitors' share"], "answer": 2, "why": "Serviceable obtainable market is the narrowest, practically capturable part."}, {"q": "In the gold jewelry case, how many families form the target audience?", "options": ["800", "400", "280", "120"], "answer": 3, "why": "800 middle-income minus 400 male-only and 280 male-and-widow families = 120."}, {"q": "Why is a market segment called product specific?", "options": ["Segments never change", "The same population splits differently depending on the product", "Only one product per segment", "Products define geography"], "answer": 1, "why": "Same village gives different segments for detergent, soap, jewelry etc."}, {"q": "Huggies' 'hug your baby' narrative is an example of:", "options": ["Pay-per-click", "Affiliate marketing", "Content marketing", "Dynamic pricing"], "answer": 2, "why": "Storytelling that informs and resonates with persona without asking to buy."}, {"q": "Per the slides, content marketing costs ___ less than traditional marketing and generates ___ leads.", "options": ["30%, 2x", "62%, 3x", "50%, 5x", "10%, same"], "answer": 1, "why": "62% less cost, three times the leads."}, {"q": "'The aim of marketing is to make selling superfluous' is attributed to:", "options": ["Philip Kotler", "Peter Drucker", "Steve Denning", "AMA"], "answer": 1, "why": "Peter Drucker's definition."}], "slug": "L16_Marketing", "excluded": "Syllabus up to slide 61 ('optional, not in syllabus' beyond); crossed-out 5–7, 24, 53 excluded."}, {"id": "L17", "title": "Startup Valuation", "oneLiner": "How startups are valued: pre- and post-money, dilution and share allotment, factors affecting valuation, how much to raise, investor return expectations, and the valuation methods with the Venture Capital method worked through.", "examRelevance": "Supports the financing question: expect pre/post-money and percentage holding numericals, number of new shares to allot, terminal value via P/E, VC method steps, list of valuation methods and factors impacting valuation.", "sections": [{"heading": "Valuation truths", "points": ["Venture valuation models usually use net cash flow, but startup future cash flows lack visibility and most startups are not yet profitable.", "No golden rule or model; without a formal market for shares it is even more subjective; valuations vary across valuers; financials are not the only value drivers.", "Valuation is both art and science; value is what the market says, i.e. what a knowledgeable investor will pay in an arm's length transaction.", "Driven by long-run profit potential; investment decisions depend on projected returns and investors' risk perception."]}, {"heading": "Equity, dilution and terminology", "points": ["Value is in the equity. Dilution: reduction in holding. Fully diluted: includes all paid-up shares, not authorized share capital.", "Pre-money: value of equity before investors put money in. Post-money: value after investment.", "Post-money - Pre-money = amount raised (money brought in by investors).", "Pre-money depends on investors' perception of traction, future prospects and success potential. Authorized capital must be enough to accommodate new equity."]}, {"heading": "Worked example: Rs 1 crore pre-money", "points": ["Company has 1,000 shares of Rs 100 issued to cofounders; investors value it at Rs 1.0 crore, so each share is worth Rs 10,000.", "Investors bring Rs 1.0 crore: post-money Rs 2.0 crore, investors get 50%.", "Usual practice: create 1,000 fresh shares for investors; paid-up rises to 2,000 x 100 = Rs 2,00,000; value per share 200 lakh / 2,000 = Rs 10,000.", "Alternative (not the practice): founders sell 500 of their shares; money goes to founders personally; slide shows 200 lakh / 1,000 = Rs 20,000 per share.", "Number of shares relates to percentage holding, not to the quantum of money invested."]}, {"heading": "Worked example: Rs 5 crore pre-money, Rs 2 crore raised", "points": ["Post-money = 5 + 2 = Rs 7 crore; investor holding = 2 / 7 = 28.57%; founders 71.43%.", "Founders keep 1,000 shares = 71.43%, so total shares = 1,000 / 0.7143 = 1,400; investors get 400 new shares.", "Note: the slide prints 1,340 total and 340 to investors, which is an arithmetic slip; 340 / 1,340 is only about 25.4%."]}, {"heading": "Funding stages", "points": ["Own funds, then family and friends, pre-seed/seed money from accelerators and incubators; crowdsourcing for small capital.", "With traction, angel investors; with market validation and need for millions, venture capitalists: first VC round is Series A, then B, C, D.", "Valuation and dilution are decided the same way at all stages."]}, {"heading": "Methods of valuation (list)", "points": ["Cost-based / cost to duplicate; Berkus method; income-based methods; market-based methods.", "Discounted cash flow; method of multiples; venture capital method; scorecard method; replacement value method.", "Comparable companies/transactions: compare valuations of similar companies at a similar stage; more data from recently public firms, but selection bias and growth assumptions must be defended.", "DCF: value = discounted net present value of cash flows CF over periods 1..n at discount rate i, less initial investment CF0, plus discounted terminal value TV."]}, {"heading": "Factors impacting valuation", "points": ["Trend of valuation, economy, location, round size, stage of development, business sector, competitive advantage.", "Team credentials, traction and timing; USP; growth and growth potential; market structure; innovation content; protected IP.", "Market validation of product/service; customer creation speed; customer retention; customer acquisition cost."]}, {"heading": "How much to raise", "points": ["Raise enough to reach the next defined milestone: market validation, predefined growth, crossing early adopters, a market share, or next funding round.", "Avoid raising more than needed for the milestone. Early-stage investors look for rapid growth, e.g. 10X in 18 months.", "Valuation responds to milestones: prototype, product launch, first 1M users. Things take longer and cost more, so budget runway past the milestone to raise the next round."]}, {"heading": "Investor perspective and expected returns", "points": ["Investors care where and when to exit: future valuation multiple and exit time; total money needed to reach a sale value; percentage required for desired ROI (10x, 20x, 50x); desired IRR, e.g. above 25%.", "Expected returns by stage: seed/start-up IRR 82%+ (5-year ROI 20x); early stage 60% (10x); growth 40% (5x); later stage 25% (3x).", "As traction grows, investors accept lower returns because of higher competition."]}, {"heading": "Terminal value via P/E", "points": ["Terminal value = Revenue x Earnings rate (net profit %) x P/E ratio. P/E = share price / earnings per share.", "Example: sales Rs 1.0 crore at 1% profit = Rs 1,00,000; 1,000 shares gives EPS Rs 100; share price Rs 5,000 gives P/E 50.", "Exit year 5, revenue Rs 1.0 crore, NP 10%, P/E 50: TV = 1.0 x 10% x 50 = Rs 5 crore; at 20% margin, Rs 10 crore."]}, {"heading": "Venture capital method", "points": ["Steps: project sales at exit, estimate net profit, know P/E; net profit x P/E = exit value; divide by required ROI multiple = post-money; subtract investment = pre-money; factor in dilution (assumed none in between).", "Example 1: exit value $50M in year 5, investment $1M, 10X return so investor needs $10M = 20% of exit; post-money = 1 / 0.2 = $5M; pre-money $4M.", "Example 2: invest Rs 100 lakh, year-5 revenue 2,000 lakh, NP 10% = 200 lakh, P/E 25, exit value 5,000 lakh; 10X gives post-money 500 lakh; investor 20% (pre-money 400 lakh).", "Made easy: exit Rs 20 crore, 10X, post-money Rs 2 crore, investment Rs 1 crore, pre-money Rs 1 crore."]}, {"heading": "Scorecard method weights (Bill Payne, 2007)", "points": ["Strength of team 30%, size of opportunity 25%, product/technology 15%, competitive landscape 10%, partnerships/marketing 10%, later investment needed 5%, other 5% (total 100%)."]}], "cases": [{"name": "Your company: Rs 1 crore pre, Rs 1 crore investment", "crux": "Post-money Rs 2 crore, investors get 50% by issuing 1,000 new shares; per-share value Rs 10,000."}, {"name": "Rs 5 crore pre, Rs 2 crore investment", "crux": "Investor 28.57%; founders' 1,000 shares become 71.43% of 1,400 total, so 400 new shares (slide says 340, a slip)."}, {"name": "VC method $50M exit", "crux": "$1M at 10X needs 20% of exit; post-money $5M, pre-money $4M."}, {"name": "VC method Rs 100 lakh", "crux": "Exit 25 x 200 lakh = 5,000 lakh; post-money 500 lakh; investor 20%."}, {"name": "Terminal value P/E example", "crux": "Rs 1 crore revenue x 10% x P/E 50 gives Rs 5 crore; doubling margin doubles TV."}], "keyTerms": [{"term": "Pre-money value", "def": "Value of the enterprise's equity before the investor puts in money."}, {"term": "Post-money value", "def": "Value after the investment: pre-money plus amount raised."}, {"term": "Dilution", "def": "Reduction in percentage holding of existing shareholders."}, {"term": "Fully diluted", "def": "Counting all paid-up shares, not authorized capital."}, {"term": "Terminal value", "def": "Value of the business at exit, e.g. revenue x net margin x P/E."}, {"term": "P/E ratio", "def": "Share price divided by earnings per share."}, {"term": "EPS", "def": "Net profit divided by number of shares outstanding."}, {"term": "IRR", "def": "Internal rate of return investors target, e.g. above 25% per annum."}, {"term": "Venture capital method", "def": "Back-calculate post-money from projected exit value divided by required return multiple."}, {"term": "Scorecard method", "def": "Weighted comparison of a startup on team, opportunity, product, competition and other factors."}, {"term": "Arm's length transaction", "def": "Deal between independent knowledgeable parties; basis for market value."}], "formulas": [{"name": "Post-money", "expr": "Post-money = Pre-money + Amount raised", "note": "Equivalently Post-money - Pre-money = amount raised."}, {"name": "Investor holding", "expr": "Investor % = Investment / Post-money", "note": "2 / 7 = 28.57%."}, {"name": "Total shares after round", "expr": "Total = Founders' shares / Founders' %; new shares = Total - Founders' shares", "note": "1,000 / 0.7143 = 1,400; 400 new."}, {"name": "Value per share", "expr": "Post-money / Total shares", "note": "200 lakh / 2,000 = Rs 10,000."}, {"name": "EPS and P/E", "expr": "EPS = Net profit / Shares; P/E = Price / EPS", "note": "1,00,000 / 1,000 = 100; 5,000 / 100 = 50."}, {"name": "Terminal value", "expr": "TV = Revenue x Net profit % x P/E", "note": "Exit value used in VC method."}, {"name": "VC method", "expr": "Post-money = Exit value / Required ROI multiple; Pre-money = Post-money - Investment", "note": "Investor % = Investment / Post-money."}, {"name": "DCF", "expr": "Value = sum over t = 1..n of CF_t / (1 + i)^t + TV / (1 + i)^n - CF0", "note": "CF0 initial investment, i discount rate."}], "examAnswerTips": ["Always write Post-money = Pre-money + Investment and Investor % = Investment / Post-money before computing.", "To find shares to allot, divide founders' existing shares by founders' post-round percentage; do not just multiply the investor % by old shares.", "In VC method answers, list steps in order: projected sales, net profit, P/E, exit value, divide by ROI, post-money, minus investment, pre-money.", "Mention that startup valuation is subjective (art and science) and list several methods and factors for theory parts.", "Recall stage-wise expected returns (20x, 10x, 5x, 3x) to justify ROI multiple chosen.", "Trap: the slide's 1,340-share answer is wrong; correct is 1,400 total and 400 to investors."], "quiz": [{"q": "Pre-money Rs 5 crore, investment Rs 2 crore. Investor's holding?", "options": ["40%", "28.57%", "25%", "71.43%"], "answer": 1, "why": "2 / 7 = 28.57%."}, {"q": "In that case founders hold 1,000 shares. Shares to issue to investor?", "options": ["286", "340", "400", "2,000"], "answer": 2, "why": "1,000 / 0.7143 = 1,400 total, so 400 new."}, {"q": "Post-money minus pre-money equals:", "options": ["Dilution", "Amount raised", "Terminal value", "EPS"], "answer": 1, "why": "Definition from slides."}, {"q": "Exit value $50M, investment $1M, required 10X. Pre-money?", "options": ["$5M", "$4M", "$10M", "$50M"], "answer": 1, "why": "Post 50/10 = 5; pre 5 - 1 = 4."}, {"q": "Year-5 revenue 2,000 lakh, NP 10%, P/E 25. Exit value?", "options": ["500 lakh", "2,000 lakh", "5,000 lakh", "50,000 lakh"], "answer": 2, "why": "200 x 25 = 5,000 lakh."}, {"q": "Revenue Rs 1 crore, net margin 20%, P/E 50. Terminal value?", "options": ["Rs 5 crore", "Rs 10 crore", "Rs 1 crore", "Rs 50 crore"], "answer": 1, "why": "1 x 0.2 x 50 = 10 crore."}, {"q": "Net profit Rs 1,00,000, 1,000 shares, share price Rs 5,000. P/E?", "options": ["5", "50", "100", "500"], "answer": 1, "why": "EPS 100; 5,000 / 100 = 50."}, {"q": "Typical expected 5-year ROI for seed/start-up stage investors:", "options": ["3x", "5x", "10x", "20x"], "answer": 3, "why": "Seed 20x (IRR 82%+)."}, {"q": "Highest weight in the scorecard method:", "options": ["Size of opportunity", "Strength of team", "Product/technology", "Competitive landscape"], "answer": 1, "why": "Team 30%."}, {"q": "Pre-money Rs 1 crore, investment Rs 1 crore, new shares created; founders had 1,000 shares. Value per share after the round?", "options": ["Rs 100", "Rs 5,000", "Rs 10,000", "Rs 20,000"], "answer": 2, "why": "200 lakh / 2,000 shares = Rs 10,000."}, {"q": "Fully diluted shareholding includes:", "options": ["Authorized capital", "All paid-up shares", "Only founders' shares", "Debt"], "answer": 1, "why": "All paid-up shares, not authorized capital."}], "slug": "L17_Valuation", "excluded": "Syllabus up to slide 41 (VC method 'working backwards' etc. excluded); crossed-out 15, 19–23, 28 excluded."}];